quests[28682] = { id = 28682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einnahme der Festung", description = "Habt Ihr die Festung im Norden der Insel gesehen, {name}? Von dort aus koordiniert Festungslord Farson seine Kriegszüge.\n\nFarson verfügt über einen kleinen Trupp ergebener Gefolgsleute. Seit wir hier eintrafen, machen sie uns Ärger. Wir haben einen Erkundungstrupp vorausgeschickt, der uns seinen genauen Standort in der Festung gemeldet hat.\n\nKönnt Ihr ihn für uns erledigen?", sourceObjective = "Eure Aufgabe lautet, Festungslord Farson in der Farsonfestung zu töten. Die Farsonfestung befindet sich auf der Nordseite der Insel.", completion = "Habt Ihr ihn umgebracht? Mehrere Wochen haben wir schon versucht, ihn zu erledigen! Wir danken Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28683] = { id = 28683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausdünnen der Brut", description = "Seit Wochen versuchen wir schon, im Finsterwald Fuß zu fassen, aber dort wimmelt es nur so von Spinnen. Tut mir einen Gefallen und schaut, ob Ihr ihre Zahl soweit eindämmen könnt, dass wir einen Angriff starten können.\n\nDoch seid vorsichtig da draußen. Mir wurde berichtet, dass Anfang der Woche Allianzruppen dort gesichtet wurden.", sourceObjective = "Tötet 12 Dunkelwaldlauerer im Finsterwald. Der Finsterwald liegt direkt nördlich von hier, jenseits der Brücke auf der mittleren Insel.", completion = "Den Spinnen habt Ihr es gezeigt, {name}. Wenn wir so weitermachen, ist der Wald im Handumdrehen unser.", sourceObjectiveStatus = "unverified-source-field" }
quests[28684] = { id = 28684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine klebrige Angelegenheit", description = "Auf dieser Insel Vorräte zu sammeln, hat sich, gelinde gesagt, als schwierig erwiesen.\n\nGlücklicherweise haben wir ein gutes Angebot an Seide ausmachen können, im Finsterwald, direkt westlich von hier. Der Nachteil an der Sache ist, dass die Seide aus den Drüsen von Brutmutterspinnen gewonnen werden muss. Ich möchte, dass Ihr mir vier davon besorgt.\n\nDas sollte genügen, um die letzte Ladung Hemden fertigzustellen.", sourceObjective = "Sammelt 4 klebrige Seidendrüsen von Dunkelwaldbrutmutterspinnen im Finsterwald. Der Finsterwald liegt gleich westlich von hier, hinter der Brücke in der Mitte der Insel.", progress = "Habt Ihr die klebrigen Seidendrüsen?", completion = "Diese Drüsen sind perfekt. Wir danken Euch für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28685] = { id = 28685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst keine Waffen zurück", description = "Auf diesem Felsen kommt man nur schwer an Kampfgerät. Jedes Mal, wenn wir die Allianz abwehren, kommt es uns vor, als kämpften wir mit Stöcken und Steinen.\n\nWir haben gehört, dass Festungslord Farson im Norden der Insel einen großen Vorrat an Gewehren hat. Könnt Ihr Euch dort hinbegeben und Euch darum kümmern?\n\nVorsicht, {name}, um Farson zu schützen, schreckt seine Gefolgschaft vor nichts zurück.", sourceObjective = "Beschafft 12 rostige Gewehre aus der Farsonfestung auf der Nordseite der Halbinsel von Tol Barad.", progress = "Wie läuft's mit den Gewehren?", completion = "Vielen Dank, dass Ihr die für uns aufgetrieben habt, {name}. Es ist wirklich kein Kinderspiel, eine Schlacht ohne Gewehre zu führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28686] = { id = 28686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht die freundlichste Stadt", description = "Wart Ihr schon oben auf dem Rostberg, {name}? Ich würde Euch raten, eine frisch geschärfte Klinge mitzunehmen, wenn Ihr dorthin wollt.\n\nDie Leute in dem Dorf sehen vielleicht anständig aus, aber dort geht etwas Seltsames vor sich. Berichten zufolge erledigen sie unsere Soldaten – einen nach dem anderen. Wir haben es langsam satt. Also müsst Ihr für mich dorthin gehen und ein wenig aufräumen.\n\nErledigt so viele Dorfbewohner wie möglich und dann meldet Euch wieder bei mir, wenn Ihr fertig seid.", sourceObjective = "Kommandant Larmash möchte, dass Ihr 14 Bewohner vom Rostberg tötet. Rostberg liegt nördlich des Baradinbasislagers auf der rechten Seite.", completion = "Ich habe doch gesagt, dass das Dorf voller Verrückter ist. Ihr habt beim Aufräumen dort gute Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28687] = { id = 28687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrt einen hungrigen Mann das Fischen... oder das Stehlen", description = "Rostberg. Dieser Ort ist für uns ein Fluch und gleichzeitig ein Segen, {name}. Ich habe keine Ahnung, wo die Räuber gelernt haben, so gut zu fischen, aber ich habe jetzt auch keine Zeit, mir darüber den Kopf zu zerbrechen.\n\nIhr müsst dorthin gehen und so viele ihrer Fischreserven wie nur möglich stehlen. Wir leben von Abfällen, seit wir die Insel wieder unter Kontrolle haben und dies ist für uns die beste Gelegenheit, ein paar anständige Lebensmittelvorräte in die Finger zu bekommen.\n\nNehmt Euch dort oben vor Herumschleichern in Acht. Berichten zufolge sind sie innerhalb der Dorfmauern ziemlich verbreitet.", sourceObjective = "Ihr müsst 22 Rostbergseebarsche aus Rostberg stehlen. Die Fische befinden sich in einer Reihe von Ständen an den Docks an der Rückseite des Dorfes. Rostberg liegt nördlich des Basislagers auf der rechten Seite.", progress = "Hattet Ihr Erfolg und habt Ihr uns ein wenig Fisch mitgebracht?", completion = "Diese Fische werden uns trefflich munden, {name}. Die Truppen anständig zu verpflegen und in guter Verfassung zu erhalten hat für uns absoluten Vorrang und Ihr habt Euch sehr für uns eingesetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28688] = { id = 28688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Das Nördliche Schlingendorntal!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Kommandant Aggro'gosh im Basislager Grom'gol zu melden. Der Kommandant benötigt Eure Hilfe dabei, die Nachschublinien offen und frei von Störungen durch Einheimische und die lästigen Allianzler zu halten.\n\nUm zu Grom'gol zu gelangen, könnt Ihr den Zeppelin an Orgrimmars östlichem Zeppelinturm oder den in der Nähe der Unterstadt nehmen.\n\nFolgt dem Ruf des Schicksals!", sourceObjective = "Meldet Euch bei Kommandant Aggro'gosh im Basislager Grom'gol im Nördlichen Schlingendorntal.", completion = "Endlich. Die Verstärkungen des Kriegshäuptlings sind eingetroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28689] = { id = 28689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vergessenen", description = "Viele Soldaten sind schon auf dieser Insel gestorben, {name}. Es ist nur recht und billig, dass wir ihnen unseren Respekt auf jede uns mögliche Art zollen.\n\nIhr müsst für mich zum Vergessenen Hügel reisen, der westlich von hier liegt. Dort müsst Ihr die gequälten Seelen unsere Waffenbrüder erlösen. Aber seid dort drüben wachsam. Es häufen sich Berichte von Aktivitäten der Untoten in diesem Gebiet.", sourceObjective = "Erlöst die Geister von 6 gequälten Seelen am Vergessenen Hügel. Seelen können kanalisiert werden, indem Ihr Eure Hände direkt auf ihre Grabsteine legt. Der Vergessene Hügel liegt westlich von hier jenseits der Rastlosen Front.", completion = "Mögen ihre Seelen in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28690] = { id = 28690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Überreste", description = "Der Vergessene Hügel ist von Zombies und Ghulen überrannt worden, seit dem Tag, an dem wir diese erbärmliche Insel für uns beanspruchten. Wir haben versucht, sie loszuwerden, aber es scheint, als kämen sie immer wieder.\n\nEiner unserer Leutnants hat vorgeschlagen, die Ghulknochen wegzuräumen, nachdem wir sie getötet haben, in der Hoffnung, dass sie nicht über Nacht wiederauferstehen. Glaubt Ihr, dass Ihr uns hierbei helfen könntet?", sourceObjective = "Ihr müsst 9 verfluchte Oberschenkelknochen von den Ghulen bergen, die sich auf dem Vergessenen Hügel herumtreiben. Der Vergessenen Hügel liegt auf der Westseite der Vergessenen Insel hinter der Rastlosen Front.", progress = "Konntet Ihr die verfluchten Oberschenkelknochen bergen? Besser Ihr als ich.", completion = "Ich hätte nicht gedacht, dass Ihr das fertig bringen würdet, {name}. Ihr steckt voller Überraschungen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[28691] = { id = 28691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberleutnant Connor", description = "Als ich das erste Mal von Oberleutnant Connor hörte, war ich ein junger Rekrut im Flammenschlund. Niemand von uns hätte je gedacht, dass er mal hier auf Tol Barad enden würde. Traurigerweise wandert er noch immer über diese elenden Inseln und richtet verheerenden Schaden an der Moral unserer Truppen an.\n\nIch möchte, dass Ihr seinem Elend ein Ende macht... und damit unserem.", sourceObjective = "Findet und tötet Oberleutnant Connor auf dem Vergessenen Hügel. Ihr findet den Vergessenen Hügel auf der westlichen Seite der Insel.", completion = "He, Ihr habt es lebendig hierher zurück geschafft! Ich kann nicht behaupten, dass Ihr der Erste wart, der dieses Unterfangen versucht hat, aber Ihr seid gewiss der Erste, der in einem Stück zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28692] = { id = 28692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinischer Magnetismus", description = "Es fällt einem schwer, auf dieser Insel brauchbare Maschinenteile zu bekommen, {name}. Wir haben versucht, die kaputte Belagerungsmaschine hier im Lager zu reparieren, aber uns gehen immer wieder die Ersatzteile aus.\n\nUnser zweites Regiment meldet ein paar demolierte Belagerungsmaschinen auf einem ehemaligen Schlachtfeld im Westen. Vielleicht findet Ihr dort ein paar Teile?\n\nEs wird nicht leicht sein, auf diesem Schlachtfeld irgendetwas zu finden, also nehmt diesen magnetisierten Schrottsammler mit. Er wird Euch sicherlich von Nutzen sein.", sourceObjective = "Ihr habt die Aufgabe erhalten, 7 Teile Belagerungsmaschinenschrott aufzutreiben. Verwendet den magnetisierten Schrottsammler an der Rastlosen Front, um die Schrottteile zu finden. Die Rastlose Front befindet sich im Westen hinter der zweiten Brücke.", progress = "Hat die Magnetapparatur tatsächlich funktioniert?", completion = "Diese Teile helfen uns wirklich weiter, {name}! Wer hätte gedacht, dass man in dem ganzen alten Schrott so viel nützliches Zeug finden würde?", sourceObjectiveStatus = "unverified-source-field" }
quests[28693] = { id = 28693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt es zu Ende", description = "Wir versuchen schon die ganze Woche, an der Front brauchbaren Schrott zu sammeln. Jedes Mal, wenn wir eine Ladung zusammengestellt haben und sie zum Lager zurückbringen wollen, werden wir von den rastlosen Soldaten aus der Umgebung angegriffen. Könntet Ihr Euch dorthin begeben und sie beseitigen?", sourceObjective = "Tötet 5 rastlose Soldaten an der Rastlosen Front. Ihr findet die Front auf der westlichen Seite der Insel, direkt vor dem Vergessenen Hügel.", completion = "Wurde auch Zeit, dass sich die Burschen jemand vorknöpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[28694] = { id = 28694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Achtung, Splitter", description = "Wart Ihr schon drüben bei Wellsons Werft, {name}? Man sollte sich unbedingt von dort fernzuhalten. Es sei denn, man hat einen guten Grund, sich dort hineinzuwagen. Unglücklicherweise muss ich Euch genau darum bitten.\n\nSeit wir diese Insel zurückerobert haben, sind wir knapp an Vorräten. Die von Geistern heimgesuchte Werft quillt über vor Nutzholz, aber jedes Mal, wenn wir eine Eskorte dorthin schicken, um das Holz zu holen, kommt sie nicht zurück.\n\nWürdet Ihr uns helfen?", sourceObjective = "Gefreiter Sarlosk hat Euch gebeten, 15 Stück Schiffsbauholz aus Wellsons Werft zu holen. Das Holz kann von den Geistern in der Werft beschafft werden und es liegt auf dem Gelände verstreut herum. Die Werft befindet sich nordwestlich von hier an der Küste.", progress = "Haben die Geister Euch fortgescheucht?", completion = "Ich hätte nicht gedacht, dass Ihr das schaffen würdet, {name}. Ihr steckt voller Überraschungen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[28695] = { id = 28695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Vorarbeiter Wellson", description = "Vorarbeiter Wellson piesackt uns schon, seit wir hierhergekommen sind. In seiner Werft gibt es große Mengen an Vorräten, die für uns extrem nützlich wären... Wenn wir nur zu ihnen gelangen könnten.\n\nEr hat seine Schergen gut im Griff und macht es uns sehr schwer, in der Werft Fuß zu fassen. Diesmal müsst Ihr Wellson für mich endgültig erledigen. Seid vorsichtig, {name}. Wir haben Berichte erhalten, nach denen es in dem Gebiet von dreckigen Allianzlern nur so wimmelt.", sourceObjective = "Tötet Vorarbeiter Wellson in Wellsons Werft. Die Werft befindet sich nördlich von hier an der Westküste.", completion = "Hervorragende Arbeit, {name}. Ich werde Euren Einsatz unverzüglich dem Oberbefehlshaber melden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28696] = { id = 28696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bom-ben-los!", description = "Wellsons Werft empfängt dauernd Vorräte von den Küstengewässern aus und das muss aufhören. Sie haben Kanonen an den Docks aufgestellt, um sich zu verteidigen, aber wenn Ihr zu ihnen durchbrechen könnt, können wir mit ihnen die Versorgungsschiffe zerstören.\n\nBegebt Euch dorthin und seht mal, was Ihr tun könnt. Erstattet mir über Eure Fortschritte Bericht.", sourceObjective = "Zerstört 10 scheußliche Versorgungsboote.", completion = "Ausgezeichnete Arbeit mit den Versorgungsbooten, {name}! Wir wussten, dass Ihr was taugt!", sourceObjectiveStatus = "unverified-source-field" }
quests[28697] = { id = 28697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterjäger", description = "Seht Ihr den Hügel mit den Türmen im Nordosten? Das ist Largos Warte und es ist nicht der schönste Ort, um daneben ein Lager zu errichten. Wir mussten uns mit Geistern und Schreckgespenstern herumschlagen, seit wir unser Basislager hier aufgeschlagen haben.\n\nKönnt Ihr Euch dorthin begeben und sie wissen lassen, dass wir nicht vorhaben, uns sobald von hier wegzubewegen? Ein paar Abschüsse in ihren Reihen sollten sie zur Räson bringen.\n\nVielen Dank für Eure Hilfe hierbei, {name}.", sourceObjective = "Tötet 14 beliebige Geister bei Largos Warte nordöstlich des Hordelagers.", progress = "Wer hat Angst vor Geistern? Ich ganz bestimmt nicht. Na gut, vielleicht im Dunklen.", completion = "Hervorragend, {name}! So bald sollten wir von den Geistern nichts mehr hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[28698] = { id = 28698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanonenkugel!", description = "Largo und seine Schergen bedienen sich an unsere Vorräten, seitdem wir hier unser Basislager aufgeschlagen haben. Es ist frustrierend, um es gelinde auszudrücken.\n\nWir haben Berichte erhalten, dass er oben in seiner Warte in den Türmen mit Blick aufs Meer Kanonenkugeln hortet. Könntet Ihr Euch dort hinauf begeben und versuchen, ein paar davon für uns zu beschaffen?\n\n{name}, vergesst nicht, dabei Ausschau nach Allianzlern zu halten.", sourceObjective = "Ihr müsst 4 Haufen Kanonenkugeln aus Largos Warte für den Gefreiten Sarlosk beschaffen. Ihr findet Largos Warte direkt nordöstlich des Basislagers.", progress = "Habt Ihr die Kanonenkugeln gefunden?", completion = "Gute Arbeit mit der Beschaffung, {name}. Diese Kanonenkugeln sollten eine Weile reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28699] = { id = 28699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Das Nördliche Schlingendorntal!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Leutnant Doren im Rebellenlager zu melden.\n\nAuch Jahre nach Colonel Kurzens Verrat gegen Sturmwind bleibt die Wahrheit über das, was geschehen ist, ein Rätsel. Helft den Überlebenden dabei, zu erfahren, was aus dem Colonel geworden ist. Reist vom Dämmerwald aus nach Süden und nachdem Ihr den Dschungel erreicht habt, folgt der Straße nach Westen, um zum Rebellenlager zu gelangen.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Leutnant Doren im Rebellenlager im Nördlichen Schlingendorntal.", completion = "Willkommen in unserem Lager, {class}, auch wenn wir hier nichts Besonderes für Euch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28700] = { id = 28700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung der Warte", description = "Es gibt nur eine Möglichkeit, wie wir Largos Warte zurückzuerobern können.\n\nIch glaube, Ihr wisst, was Ihr tun müsst, {name}. Largo ist in letzter Zeit ziemlich paranoid. Ihr solltet ihn also auf der Turmspitze finden, wo er nach seiner eingebildeten Flotte Ausschau hält.", sourceObjective = "Gefreiter Sarslok hat Euch beauftragt, Kommandant Largo in Largos Warte zu töten. Die Warte befindet sich direkt nordöstlich des Basislagers.", completion = "Ha! Endlich haben wir Largo erledigt! Sehr gut, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28701] = { id = 28701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Sicherheit", description = "Als diese Plage ausgebrochen ist, lagen glücklicherweise keine Druiden im westlichen Grabhügel. Es ist für uns jedoch noch immer eine heilige Stätte und in ihr befinden sich heilige Relikte, die schon seit langer Zeit dort unbehelligt ruhen.\n\nObwohl ich den goblinischen Kammerjägern auf eine Art vertraue, bin ich außerdem... mit den Besonderheiten vertraut, die ihr Volk ausmachen. Bitte bergt aus dem Grabhügel so viele Relikte, wie Ihr finden könnt und bringt sie zu mir zurück, damit sie nicht beschädigt werden. Sie befinden sich in Urnen, die in kleinen Nischen im Hügel aufbewahrt werden.", sourceObjective = "Beschafft 5 Relikte von Sternfall aus den Grabhügeln von Ban'Thallow.", progress = "Ich hoffe, sie waren unversehrt...", completion = "In Euren Augen mögen sie vielleicht nichts Besonderes sein, aber diese Relikte sind für das Volk von Sternfall von unschätzbarem Wert. Ihr seid sehr gütig, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28702] = { id = 28702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Das Schlingendornkap!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Bronwyn Hackschlag an der Grabungsstätte der Forscherliga zu melden.\n\nDie Expedition der Forscherliga braucht Eure Hilfe bei der Sicherung der Grabungsstätte und der Bekämpfung der plündernden Oger. Reist vom Nördlichen Schlingendorntal Richtung Süden und folgt der Straße zur Grabungsstätte der Forscherliga.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Bronwyn Hackschlag an der Grabungsstätte der Forscherliga am Schlingendornkap.", completion = "Es ist gut, dass Ihr hier seid, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28703] = { id = 28703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinab in den Hügel", description = "Ich habe noch immer keine Ahnung, wo all diese Käfer hergekommen sind. Ich vermute, dass der Kataklysmus ein paar ihrer Nester im Untergrund aufgewühlt hat, von denen wir keine Ahnung hatten, dass sie existierten.\n\nAber es nützt nichts, sich darüber den Kopf zu zerbrechen, da wir sie ohnehin töten!", sourceObjective = "Tötet 10 Krabbler der Kaltlaurer und 5 Wühler der Kaltlaurer.", completion = "Hey, gute Arbeit!\n\nWenn Ihr irgendwann Lust habt, wieder hierher zu kommen und noch ein paar Käfer völlig ohne weitere Belohnung zu töten, tut Euch keinen Zwang an!", sourceObjectiveStatus = "unverified-source-field" }
quests[28704] = { id = 28704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Das Schlingendornkap!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Sassy Hartzang in Hartzangs Versteck zu melden. Sie benötigt Eure Hilfe mit ein paar Piraten und Naga, die den Dschungel überrannt haben. \n\nReist zu Hartzangs Versteck, indem Ihr vom Nördlichen Schlingendorntal Richtung Süden reist und nach der Stadt südwestlich der Arena der Gurubashi Ausschau haltet.\n\nFolgt dem Ruf des Schicksals!", sourceObjective = "Meldet Euch bei Sassy Hartzang in Hartzangs Versteck am Schlingendornkap.", sourceObjectiveStatus = "unverified-source-field" }
quests[28705] = { id = 28705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Die Scherbenwelt!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Generalleutnant Orion an den Stufen des Schicksals zu melden.\n\nDort werden Eure Fähigkeiten benötigt, um die Anwesenheit der Brennenden Legion auf den zerschmetterten Resten der Scherbenwelt zu bekämpfen.\n\nBegebt Euch zu Orgrimmars Kluft der Schatten und verwendet das Portal in der Nähe des Magierlehrers, um in die Verwüsteten Lande zu gelangen. Dann reist durch das Dunkle Portal selbst, um die Höllenfeuerhalbinsel zu erreichen.\n\nFolgt dem Ruf des Schicksals!", sourceObjective = "Meldet Euch bei Generalleutnant Orion an den Stufen des Schicksals auf der Höllenfeuerhalbinsel.", completion = "Bereitet Euch auf den Kampf vor. Die Horde braucht Euch hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[28706] = { id = 28706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuchert sie aus", description = "Meine Geschwister sind schon weiter unten im Hügel und versuchen, mit diesen Käfern fertigzuwerden, aber sie werden langsam von ihnen überwältigt. Ich sage, es wird Zeit, diese Höhle auszuräuchern.\n\nNehmt diese Räucherapparate. Aber setzt sie nicht selbst ein. Dazu muss man ein gut ausgebildeter Profi sein und das richtige Timing haben. Findet meine Geschwister und verteilt die Geräte an sie.\n\nRemma sollte sich in der Nähe des Eingangs befinden. Begebt Euch den Gang entlang und haltet Euch rechts, sobald Ihr die Rampe hinuntergeht.", sourceObjective = "Bringt die Kiste mit Käfertodräucherapparaten zu Remma Vorhangfeuer im Grabhügel von Ban'Thallow.\n\nBereitgestellter Gegenstand:", completion = "Ihr bringt mir den Käfertod, wie? Ich schätze, dann geht es wohl nicht anders.", sourceObjectiveStatus = "unverified-source-field" }
quests[28707] = { id = 28707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuchert sie noch mal aus", description = "Ich werde den hier jetzt vorbereiten.\n\nDer nächste ist für Marcy. Sie ist weiter unten im Hügel. Geht diesen Gang entlang und sucht nach ihr in der nächsten Hauptkammer.", sourceObjective = "Bringt die Kiste mit Käfertodräucherapparaten zu Marcy Vorhangfeuer im Grabhügel von Ban'Thallow.", progress = "Ich habe nicht damit gerechnet, hier unten einen Fremden zu treffen!", completion = "Räucherapparate? Von Rinno? Oje...", sourceObjectiveStatus = "unverified-source-field" }
quests[28708] = { id = 28708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Die Scherbenwelt!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Kommandant Duron auf der Höllenfeuerhalbinsel zu melden.\n\nDie Expeditionskräfte benötigen Eure Unterstützung bei der Bekämpfung der Dämonenarmeen der Brennenden Legion! Verwendet das Portal auf der mittleren Ebene des Turms im Magierviertel, um in die Verwüsteten Lande zu gelangen. Dann reist durch das Dunkle Portal, um die Stufen des Schicksals in der Scherbenwelt zu erreichen.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Kommandant Duron an den Stufen des Schicksals auf der Höllenfeuerhalbinsel.", completion = "Die Expedition braucht Eure Hilfe, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28709] = { id = 28709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Nordend!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Rekrutierungsoffizier Blythe in der Valianzfeste in der Boreanischen Tundra zu melden.\n\nDie Expedition Valianz benötigt Eure Hilfe dabei, die Kräfte der Geißel unter Kontrolle zu halten und die zivilisierten Länder zu sichern! Begebt Euch zu den Docks von Sturmwind und nehmt das Schiff nach Norden zur Valianzfeste.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Meldet Euch bei Rekrutierungsoffizier Blythe in der Valianzfeste in der Boreanischen Tundra.", completion = "Die Expedition braucht Eure Hilfe, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28710] = { id = 28710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuchert sie schon wieder aus", description = "Rinno hätte uns ruhig mehr Unterstützung schicken können, als nur Euch, {class}! Dieser Schmarotzer...\n\nIch werde den hier jetzt aufstellen. Begebt Euch von diesem Raum aus nach Norden durch den Gang und sucht nach Sana. Sie hat sich vermutlich in der letzten Kammer verirrt. Also seht auch in den Seitengängen nach, sobald Ihr dort eintrefft.", sourceObjective = "Bringt die Kiste mit Käfertodräucherapparaten zu Sana Vorhangfeuer im Grabhügel von Ban'Thallow.", progress = "Was macht Ihr hier?", completion = "Rinno hat Euch geschickt? Und ihr habt... Räucherapparate dabei? Pfui!", sourceObjectiveStatus = "unverified-source-field" }
quests[28711] = { id = 28711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Nordend!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend beim Rekrutierungsoffizier des Kriegshymnenklans in der Kriegshymnenfeste zu melden.\n\nDie Kriegshymnenoffensive benötigt Eure Hilfe dabei, die anhaltende Bedrohung durch die Untoten der Geißel zu beenden.\n\nNehmt den Zeppelin an Orgrimmars westlichem Zeppelinturm zur Kriegshymnenfeste und stellt Euch beim Rekrutierungsoffizier vor.\n\nFolgt dem Ruf des Schicksals!", sourceObjective = "Meldet Euch beim Rekrutierungsoffizier des Kriegshymnenklans in der Kriegshymnenfeste in der Boreanischen Tundra.", completion = "Die Kriegshymnenoffensive könnte mehr von Eurer Sorte gebrauchen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28712] = { id = 28712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftritt der Drachenkönigin", description = "Hallo, {race}. Ich wünschte, unser Treffen würde unter erfreulicheren Umständen stattfinden. Die Welt hängt an einem seidenen Faden und alles, was die Titanen erschaffen haben, steht auf dem Spiel.\n\nEs betrübt mich zutiefst, aber mein Urteil ist unumstößlich. Todesschwinge, die entsetzliche Kreatur, die einst der Erdwächter und mein Freund war, muss vernichtet werden.\n\nIch habe eine Stätte oben im Hochland errichtet. Sie liegt westlich des Zinnoberrefugiums. Dort kann ich es zu Ende bringen. Sucht nach dem Kreis des Lebens. Darin befindet sich Lirastrasza. Sprecht mit ihr. Ich werde dort zu Euch stoßen.", sourceObjective = "Sprecht mit Lirastrasza im Kreis des Lebens im Schattenhochland.", completion = "Hallo, {race}. Ich habe gehört, dass Ihr bei unserem Vorstoß gegen Grim Batol von großer Hilfe wart. Habt Dank!\n\nAlexstrasza hat diesen Boden geheiligt, in der Hoffnung damit Todesschwinge hierher zu locken. Sie wird eine Zeremonie durchführen, um ihn hervorzulocken und ihn dann in diesem heiligen Kreis zu vernichten.\n\nHoffen wir, dass ihr Plan aufgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28713] = { id = 28713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gleichgewicht der Natur", description = "Seid gegrüßt, {name}. Ich bin Ilthalaine. Meine Aufgabe im Laubschattental besteht darin, junge Helden wie Euch auszubilden, {class}, und sicherzustellen, dass das Naturgleichgewicht erhalten bleibt.\n\nDer Frühlingsregen war dieses Jahr besonders reichlich. Einige Geschöpfe des Dschungels haben davon profitiert und andere haben darunter gelitten. Unglücklicherweise ist die Zahl der Nachtsäbler zu groß geworden und sie werden andere Kreaturen ausrotten, wenn sie nicht selbst dezimiert werden.\n\nReist weiter, {class}, und dünnt die Population der Nachtsäbler aus, damit die Harmonie der Natur erhalten bleibt.", sourceObjective = "Tötet 6 junge Nachtsäbler.", progress = "Ihr habt noch immer zu tun, {name}. Kehrt zu mir zurück, sobald Ihr die Population der Nachtsäbler dezimiert habt.", completion = "Ihr seid Eurer Pflicht vorbildlich nachgekommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28714] = { id = 28714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbtes Teufelsmoos", description = "Ihr scheint zu wissen, was Ihr tut. Vielleicht kann ich Euch mit einer etwas gewichtigeren Aufgabe betrauen.\n\nWie Ihr vielleicht wisst, wurde die Verderbnis in Teldrassil angeblich ausgemerzt. Und doch geht etwas Verdorbenes um. Die Kreaturen haben sich nicht beruhigt und es plagen uns weiter alle möglichen Probleme.\n\nIhr müsst Euch um die Grellkin kümmern, die sich im Westen versammelt haben und während Ihr dort seid, möchte ich, dass Ihr sie nach Teufelsmoos absucht. Dies wird mir helfen, herauszufinden, woher diese fortgesetzte Verderbnis stammt.", sourceObjective = "Sammelt 6 Teufelsmoose von den Grellkin im Westen von Ilthalaine.", progress = "Bestätigt meinen Verdacht, {name}. Bringt mir das Teufelsmoos von den Grellkin.", completion = "Für Euren Dienst an den Geschöpfen des Laubschattentals habt Ihr Euch eine Belohnung verdient, {name}.\n\nMeine Sorge habt Ihr jedoch bestätigt. Die Grells sind trotz der Segnung Teldrassils noch immer vom Teufelsmoos befleckt. Etwas Finsteres ist in dem Baum verblieben. Ich kann nur hoffen, dass der Furbolgstamm der Knarzklauen frei von Verderbnis ist, oder wir sind noch immer in großer Gefahr.\n\nIch werde mich näher damit befassen und mich mit denjenigen in Verbindung setzen, die uns helfen können. Habt Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28715] = { id = 28715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonische Diebe", description = "Bösartige kleine Grells! Sie haben schon wieder etwas von unseren Lebensmittelvorräten gestohlen.\n\nWenn es Euch nichts ausmacht, mir zur Hand zu gehen: Sie haben sicherlich meine gestohlenen Taschen in ihrem Lager im Westen. Ich werde Euch mit Freuden belohnen, wenn ihr sie mir zurückbringt.", sourceObjective = "Beschafft Melithars gestohlene Taschen in der Nähe der Grellkin im Westen.", progress = "Ich habe keine Vorräte für meine Kunden, bis meine gestohlenen Waren wieder bei mir sind. Wie ist es gelaufen?", completion = "Elune sei gepriesen! Und Ihr ebenfalls, {class}.\n\nViele junge Nachtelfen benötigen diese dringend, aber es ist mir eine große Freude, Euch eine dieser Taschen als Belohnung zu überreichen. Ich bin mir sicher, sie wird Euch von Nutzen sein.\n\nIch wünsche Euch eine sichere Reise.", sourceObjectiveStatus = "unverified-source-field" }
quests[28716] = { id = 28716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Das Schattenhochland!", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend im Thronraum von Burg Sturmwind einzufinden.\n\nKönig Wrynn benötigt einen vertrauenswürdigen und erfahrenen Helden für eine Aufgabe von höchster Wichtigkeit.\n\nBurg Sturmwind befindet sich im östlichen Teil von Sturmwind.\n\nFür den Ruhm und die Ehre der Allianz!", sourceObjective = "Sprecht mit König Varian Wrynn in Burg Sturmwind in Sturmwind.", completion = "Wir sind erfreut, dass Ihr unserem Ruf gefolgt seid, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28717] = { id = 28717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Das Schattenhochland!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Garrosh Höllschrei in der Feste Grommash zu melden.\n\nDer Kriegshäuptling braucht Eure Hilfe bei der Vorbereitung eines glorreichen Angriffs auf das Schattenhochland und unsere beiden Feinde: die Allianz und den Schattenhammer.\n\nTrefft den Kriegshäuptling in der Feste Grommash, die mitten in Orgrimmars Tal der Stärke liegt.\n\nFolgt dem Ruf des Schicksals!", sourceObjective = "Meldet Euch bei Garrosh Höllschrei in der Feste Grommash in Orgrimmar.", completion = "Bald wird der Angriff auf das Schattenhochland beginnen und ich will, dass Ihr daran teilnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28718] = { id = 28718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo es Rauch gibt, ist auch köstliches Fleisch", description = "Heda, {class}... Mögt Ihr Fleisch? Oder besser: mögt Ihr Geld? \n\nEiner meiner Cousins zweiten Grades verdient sich eine goldene Nase mit Tiefkühlfleisch. Er hat eine Räuchergrube oben im Norden eingerichtet und er braucht Hilfe bei der Jagd auf all die gefährlichen Bestien, die gewöhnlich so vorzüglich schmecken.\n\nFleischfresser zahlen gut. Ich bin hier zu sehr in diesem Grabhügel beschäftigt. Was habe ich mir nur dabei gedacht? Ich kann also den Tipp genauso gut an jemanden wie Euch weitergeben, {race}.\n\nSein Name ist Jez. Begebt Euch nach Nordosten und haltet einfach Ausschau nach dem Rauch!", sourceObjective = "Findet Jez Gutmampf in Gutmampfs Räuchergrube in Winterquell.", completion = "Seht Euch um. Das ist das größte Jagdreservat in ganz Kalimdor, das in der Hand von Goblins ist! Ich habe eine Abschusslizenz und esse alle Kreaturen, die sich zwischen hier und der Ewigen Warte auf dem Schnee bewegen... Und eins kann ich Euch sagen: Sie schmecken prima!", sourceObjectiveStatus = "unverified-source-field" }
quests[28719] = { id = 28719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wenig gewöhnungsbedürftig", description = "Viele finden das Fleisch des Splitterzahnbären etwas zu gewöhnungsbedürftig. Ich bin anderer Meinung, obwohl es mir nicht zusteht, den Geschmack von anderen zu verurteilen.\n\nDie Splitterzahnraufer jedoch – ihre braunfelligen Cousins im Süden – haben ein sehr viel zarteres Fleisch, besonders an ihren Tatzen. Ich habe gehört, dass die Schnauze ebenfalls als Delikatesse gilt.\n\nSetzt Eure Jagd fort, {name}. Zeigt mal, ob Ihr diese Splitterzahnraufer für den ollen Francis in den Sack stecken könnt.", sourceObjective = "Tötet 15 Splitterzahnraufer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28722] = { id = 28722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yetiphobie", description = "Es ist alles bereit, {name}!\n\nJetzt habe ich meiner Freundin Legacki erzählt, dass ich eine Überraschung für sie habe. Und da kommt Ihr ins Spiel!\n\nIch werde Euch meinen mechanischen Yeti geben und Euch gebührt die Ehre, sie damit zu überraschen. Ihr findet sie auf der anderen Seite der Ewigen Warte in der Nähe des Gasthauses.\n\nBegebt Euch zu Ihr und schaltet den Yeti ein... Ich werde von hier aus zusehen!", sourceObjective = "Erschreckt Legacki mit Umis mechanischem Yeti.", progress = "Damit wird sie niemals rechnen!", completion = "Ha! Sie wird es sich zweimal überlegen, bevor sie sich wieder über meine Ideen lustig macht!\n\nHabt Dank für Eure Hilfe, {name}. Ohne Euch hätte ich nie so viel Spaß gehabt!", sourceObjectiveStatus = "unverified-source-field" }
quests[28723] = { id = 28723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondpriesterin", description = "Jetzt, wo Ihr Euch in Eurer neuen Fähigkeit geübt habt, seid Ihr vielleicht bereit uns beim Kampf gegen die Verderbnis zu helfen, die das Laubschattental heimsucht.\n\nMondpriesterin Dentaria Silbertal hat uns ihre Hilfe angeboten. Ihr solltet sie zwischen den beiden Teichen nördlich unseres Großen Baumes finden. Schlagt einen Bogen um den Baum, um zu ihr zu gelangen und helft ihr so gut Ihr könnt, {class}.", sourceObjective = "Sprecht mit Dentaria Silbertal zwischen den beiden Teichen im Zentrum des Laubschattentals.", completion = "Es ist gut, dass Ihr gekommen seid. Es scheint, Eure Ausbildung schreitet schnell voran.", sourceObjectiveStatus = "unverified-source-field" }
quests[28724] = { id = 28724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iverrons Gegengift", description = "Unser Freund Iverron ist vom Gift der Waldweberspinne befallen worden. Ich kann dafür sorgen, dass sich sein Zustand nicht verschlechtert, aber ich brauche jemanden, der eine Zutat sammelt, damit ich ihm ein Gegengift mischen kann.\n\nÜberall um die Teiche herum solltet Ihr Mondblütenlilien finden. Diesen Blumen wohnt eine große Heilkraft inne. Wenn ich sie gemeinsam mit anderen Zutaten verwende, die ich bereits habe, kann ich Iverron wieder gesund machen.\n\nWürdet Ihr sie für mich sammeln? Es müsste viele in Sichtweite von hier in der Nähe des Ufers geben.", sourceObjective = "Sammelt 7 Mondblütenlilien.", progress = "Unserem lieben Freund geht es nicht sehr gut - trotz meiner Pflege. Habt Ihr mir gebracht, was ich benötige?", completion = "Die sind perfekt. Habt Dank, {name}. Besonders für Eure Schnelligkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28725] = { id = 28725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschützerin des Waldlandes", description = "Nun muss ich Euch um einen Gefallen bitten, der durchaus gefährlich ist. Seltsame Kunde ist mir durch das Tuscheln der Waldgeister zu Ohren gekommen. Die rätselhafte Beschützerin des Waldlandes, Tarindrella, ist ins Laubschattental zurückgekehrt.\n\nDie Anwesenheit der Dryade war das letzte Mal vor der Segnung von Teldrassil zu spüren. Irgendetwas muss im Argen liegen, wenn sie zurück in dieses Land gereist ist.\n\nSucht nach Tarindrella in der Schattenweberhöhle im Norden. Es ist gefährlich, aber wir werden dieses Gegengift sicherheitshalber bereithalten.", sourceObjective = "Sucht nach der Dryade mit dem Namen Tarindrella in der Schattenweberhöhle am nördlichen Ende des Laubschattentals.", completion = "Ich sehe, Ihr habt mich gefunden, {race}. Dentaria war weise genug, Euch zu mir zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[28726] = { id = 28726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis der Waldweber", description = "Ich hatte gehofft, niemals wieder wegen solch düsterer Angelegenheiten nach Teldrassil zurückzukehren. Ich hoffte, dass hier die Verderbnis inzwischen vollständig ausgerottet sei. Etwas Schändliches geht um.\n\nDiese Spinnen leiden viel stärker unter der Verderbnis als die anderen Tiere der Umgebung. Sie werden zu einer Gefahr für mein Volk und zu einer Gefahr für den Wald. Wir müssen Ihre Anzahl dezimieren, aber noch wichtiger: Wir müssen die Quelle der Verderbnis finden, die sie plagt.\n\nIch werde mit Euch kommen und Euch in dieser Sache unterstützen.", sourceObjective = "Tötet 12 Waldweberspinnen.", progress = "Dies ist eine abscheuliche Arbeit. Es schmerzt mich, dass wir so viel Gewalt über ein Geschöpf des Waldes bringen müssen, sei es nun verdorben oder nicht.", completion = "Die Verderbnis, unter der diese Spinnen zu leiden haben, ist nicht nur oberflächlich. Es kann weder Magie sein noch unterschwellige Böswilligkeit. Es ist in sie hineingezüchtet worden.\n\nEs ist offensichtlich, was unsere nächste Aufgabe ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[28727] = { id = 28727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abscheuliche Berührung", description = "Wenn diese Spinnen alle schon mit der Verderbnis in ihren Adern geboren wurden, dann muss ihre Brutmutter die Quelle dieses Bösen sein.\n\nBrechen wir auf in den äußersten nördlichen Winkel dieser Höhle und suchen wir Githyiss die Üble. Sie trägt die Antwort, die wir suchen, in sich.", sourceObjective = "Tötet Githyiss die Üble am Nordende der Schattenweberhöhle.", progress = "Ich verehre diese Wälder. Ich will, dass sie vollständig von dieser Verderbnis befreit werden. Wenn ich das nächste Mal zurückkehre, will ich es froheren Herzens tun.", completion = "Githyiss und ihre Brut wurden von diesem Totem verdorben. Dies ist ein Totem der Furbolgs.\n\nDies ist tatsächlich sehr beunruhigend. Es bedeutet, dass die Knarzklauen noch immer eine Gefahr für diesen Wald darstellen. Wir haben uns zu früh zu sicher gefühlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28728] = { id = 28728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anzeichen der Dinge, die da kommen werden", description = "Ich werde der Spur der Knarzklauen nachgehen und dieser Verderbnis bis zu ihrer Quelle folgen. Falls Ihr jemals Athridas Bärenfell in Dolanaar begegnet: Er weiß über die Probleme dieses Waldes genauestens Bescheid und er kann Euch raten, wie Ihr weiter helfen könnt. \n\nIch bin mir sicher, dass wir uns wiedersehen. Vielleicht könntet Ihr mir dabei helfen, die Quelle dieser Verderbnis zum Versiegen zu bringen, sobald wir sie ausgemacht haben. Jetzt werde ich Euch zurück zu Dentaria bringen, sodass Ihr Eure Ausbildung abschließen könnt. Habt Dank für alles, was Ihr für uns getan habt, {name}.", sourceObjective = "Sprecht mit Dentaria Silbertal zwischen den beiden Teichen im nördlichen Laubschattental.", completion = "Ihr seid zurückgekehrt! Es ist gut, dass Ihr hier seid. Es scheint, Ihr habt die Quelle der Verderbnis erfolgreich bekämpft, die große Teile des Laubschattentals bedroht hat.\n\nTeldrassil leidet noch immer und bedarf weiterhin unserer Aufmerksamkeit, aber wir können einen Augenblick dafür aufwenden, Eure Ausbildung hier im Laubschattental abzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28729] = { id = 28729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Krone von Azeroth", description = "Als Teil des Abschlussrituals Eurer Ausbildung hier im Laubschattental werdet Ihr etwas über unsere jüngere Geschichte erfahren.\n\nDafür müsst Ihr eine Aufgabe erfüllen. Geht zum Mondbrunnen im Nordosten und füllt eine Phiole mit seinem Wasser. Während Ihr dort seid, werdet Ihr einen flüchtigen Augenblick unserer Magie zu Gesicht bekommen und etwas über unsere Vergangenheit erfahren.\n\nWenn Ihr dort fertig seid, bringt das Wasser zu mir zurück und ich werde Euch weitere Anweisungen geben.", sourceObjective = "Füllt die Kristallphiole am Mondbrunnen im nordöstlichen Laubschattental.", progress = "Unsere jüngere Geschichte ist voller Zwietracht und Gewalt. Es gibt noch immer viel, womit wir uns arrangieren müssen.", completion = "Gut gemacht, {name}. Ihr habt noch eine Aufgabe vor Euch, bevor Ihr vom Laubschattental zur offenen Wildnis von Teldrassil reist.", sourceObjectiveStatus = "unverified-source-field" }
quests[28730] = { id = 28730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvolle Wasser", description = "Tenaron Sturmgewalt überwacht alles, was in diesem Tal geschieht. Er hat seinen Wohnsitz auf der Spitze Aldrassils.\n\nFalls Ihr nach Süden blickt, werdet Ihr den unteren Teil der Rampe sehen, die zu ihm hinaufführt. Steigt diese Rampe hinauf und vollendet Eure Ausbildung.\n\nEs war wundervoll, Euch kennengelernt zu haben, {name}. Ich bin sehr stolz, zu wissen, dass unter den jungen Nachtelfen auch solche sind, die so selbstlos und voller Leben sind wie Ihr. Ihr werdet große Taten für unser Volk vollbringen. Ihr werdet große Dinge in dieser Welt tun.\n\nMögen wir uns bald wiedersehen.", sourceObjective = "Bringt die gefüllte Kristallphiole zu Tenaron Sturmgewalt auf der Spitze von Aldrassil im Laubschattental.", progress = "Die Mondbrunnen enthalten die Wasser des Brunnens der Ewigkeit, der uralten Quelle der Magie, die so viele Schrecken über unsere Welt gebracht hat.\n\nDie Druiden nutzen die Eigenschaften des Wassers, die Schildwachen verehren die Brunnen als Schreine der Elune und jetzt richten sogar die zurückgekehrten Hochgeborenen sehnsüchtige Blicke auf die Brunnen.", completion = "Ihr habt also den ersten Teil der Nachwirkungen von der Schlacht am Hyjal erfahren. Es gibt noch viel mehr für Euch zu erfahren und die Aufgabe, die Ihr hier begonnen habt, wird sich für den Rest Eurer Reise durch Teldrassil bis nach Darnassus fortsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28731] = { id = 28731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil: Gebt das Wissen weiter", description = "Es gibt noch mehr, was ich Euch über die Mondbrunnen erzählen könnte und über Teldrassil, aber ich muss Euch nun fortschicken. Corithras Mondzorn wird Euch erwarten. Ich habe die Phiole mit dem Wasser, das Ihr gebracht habt, in dieses Gefäß gefüllt.\n\nSucht nach Corithras. Ihr findet ihn am Mondbrunnen in Dolanaar. Folgt der Straße südlich von Aldrassil aus dem Laubschattental hinaus und geht weiter entlang der Pflastersteine, wenn sich die Straße nach Westen wendet.\n\nAchtet aber darauf, auf der Straße zu bleiben, {name}. In den Wäldern lauern neuerdings gefährliche Ungeheuer.", sourceObjective = "Bringt das teilweise gefüllte Gefäß zu Corithras Mondzorn in Dolanaar.", progress = "Seid gegrüßt, {class}. Welchem Anlass verdanke ich die Freude unserer Zusammenkunft?", completion = "Ah, ich verstehe. Tenaron hat Euch gesandt. Nun gut, es scheint, dass wir viel zu bereden und noch mehr zu tun haben.\n\nBevor wir uns um die zu erledigende Aufgabe kümmern, solltet Ihr die Lektion dieses Mondbrunnens erlernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28732] = { id = 28732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das kann nur eins bedeuten...", description = "Raz und ich wurden von den Wächtern des Hyjal beauftragt, das Wiederauftauchen von Ragnaros in unsere Welt zu untersuchen. Lasst mich weiterziehen und bestätigen, dass er zurück ist und dass er erzürnt ist! Wir haben außerdem Beweise, dass diese Schattenhammerkultisten Elementare von hier zu den Schwarzfelshöhlen in den Östlichen Königreich bringen.\n\nRaz und ich waren auf dem Weg dorthin, um die Sache zu untersuchen. Wir haben in der Maulwurfmaschine noch Platz für eine Person, falls Ihr interessiert seid? Trefft uns einfach draußen und unsere Reise kann beginnen.", sourceObjective = "Nehmt Pips Maulwurfmaschine zum Schwarzfels.", progress = "HILFE! HILFE!", completion = "Oje, Raz wurde gefangengenommen! Sobald wir drin waren, haben uns ein dutzend Schattenhammerkultisten und ein dicker, fetter Oger angegriffen. Ich bin losgerannt, während Raz versucht hat, sie abzuwehren. Wir müssen ihn retten, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28733] = { id = 28733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflanzenkunde für Anfänger", description = "HILFE! HILFE! Durchgedrehte Untote greifen meinen Hof an! Dieser verrückte Aufseher drüben bei den Schlickfeldern ist vermutlich für diese Sauerei verantwortlich. Helft mir, die Zombies abzuwehren!", sourceObjective = "Überlebt eine riesige Zombiewelle.", completion = "PUH! Das war knapp! Ihr seid ein echtes Naturtalent, wenn es um diese Pflanzen geht, {class}. Wisst Ihr, ich habe die Samen hier von den Verlorenen Inseln mitgebracht. Ich bin mir sicher, sobald ich alles über sie herausgefunden habe, werde ich ein Vermögen mit dem Verkauf von tödlichen Blumen machen!\n\nWa... SEHT! ES KOMMEN NOCH MEHR!", sourceObjectiveStatus = "unverified-source-field" }
quests[28734] = { id = 28734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gefallen für Melithar", description = "Ihr solltet mit Melithar sprechen. Ich glaube, er hatte bereits einige Probleme mit den Grells.\n\nIch schätze, er kann Euch Platz anbieten, an dem Ihr einiges von Eurem Hab und Gut verstauen könnt, falls Ihr ihm helft.", sourceObjective = "Sprecht mit Melithar Hirschhaupt im Laubschattental.", completion = "Ilthalaine hat Euch geschickt? Es war weise von ihm, das zu tun. Ich brauche in der Tat Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28735] = { id = 28735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Kammer der Einäscherung!", description = "Es war ein Hinterhalt, {name}! Kaum waren wir drin, griff uns ein dicker, fetter Oger namens Rom'ogg Knochenbrecher an! Raz hat mich mutig verteidigt, während ich davongerannt bin, um mich zu verstecken. Ich musste zusehen, wie sie ihn bewusstlos schlugen und ihn dann zu einem Ort brachten, den der Fette \"Kammer der Einäscherung\" nannte. Ich glaube, sie ist in der Halle auf der anderen Seite der Brücke.\n\nIch habe zu viel Angst, um auch nur einen Schritt weiter zu gehen. Nehmt meinen Allzwecktaucherhelm und sucht nach Raz. Durch den Helm kann ich mit Euch sprechen.\n\nUnd wenn Ihr diesen Oger findet, tötet ihn!", sourceObjective = "Tötet Rom'ogg Knochenbrecher.", completion = "<Finkles Helm knistert vor statischer Aufladung.>\n\nRAZ! Was haben sie ihm angetan!? FOLGT IHM!", sourceObjectiveStatus = "unverified-source-field" }
quests[28736] = { id = 28736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer vom Himmel", description = "Die Überreste von Schnottz' Organisation halten sich hier beharrlich auf dem Aufstieg des Schöpfers, was dieses Gebiet für jeden, der sich nähert, zur Todesfalle macht.\n\nEs gibt reichlich Munition, aber ohne einen guten Beobachter schieße ich einfach blindwütig umher.\n\nSpringt auf und geht mir zur Hand. Diesen Soldaten wird das Hören und Sehen vergehen!", sourceObjective = "Steigt in die beschlagnahmte Artillerie und verwendet sie, um 100 Infanteristen von Schnottz zu töten.", progress = "Hier gibt es reichlich Ziele, {class}.", completion = "Der Feind auf dem Aufstieg des Schöpfers bleibt eine Bedrohung, aber dank Eurer Hilfe haben wir ihrer Anzahl und ihrem Kampfgeist einen ernsthaften Schlag versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28737] = { id = 28737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sind wir hier?", description = "<Pips Helm versetzt Euch einen leichten Stromschlag.>\n\nWas ist das für ein Ort? Es sieht aus, als würden sie dem Netherdrachen schreckliche Dinge antun. Seine Energie wird in die Frau dort geleitet! Wir müssen das Ritual aufhalten!\n\nTötet Corla, um diese Halle hinter Euch zu lassen!", sourceObjective = "Tötet Corla, Botin des Zwielichts.", progress = "<Pips Helm gibt ein statisches Knistern von sich.>", completion = "<Pips Helm gibt ein statisches Knistern von sich.>\n\nUns bleibt nicht viel Zeit. Sieht aus, als wäre Raz verletzt. Wenn wir ihn rechtzeitig erreichen, haben wir vielleicht sogar eine Chance, ihn in einen gewöhnlichen Orc zurückzuverwandeln!\n\n<Ihr fühlt einen stechenden Schmerz im Hinterkopf und hört das Klingeln von Münzen>\n\nEntschuldigt das. Ich dachte, ich würde Euch etwas Gold durchschicken... für Eure Mühen und so...", sourceObjectiveStatus = "unverified-source-field" }
quests[28738] = { id = 28738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zwielichtschmiede", description = "<Pips Helm summt vor Energie.>\n\nVerdammt nochmal! Raz hört einfach nicht auf! Es ist, als hätte ihn eine brennende Rachsucht gegen alles mit Zwielicht im Namen ergriffen! Sieht so aus, als müssten wir den Zwielichtrüstungsschmied Karsh Stahlbieger ausschalten, wenn wir den Raum hinter uns lassen und zu Raz aufschließen wollen.", sourceObjective = "Tötet Karsh Stahlbieger.", progress = "<Pips Helm gibt ein statisches Knistern von sich.>", completion = "<Pips Helm gibt ein statisches Knistern von sich.>\n\nDas sollte ihrem Arsenal ein Ende bereitet haben... zumindest vorerst.\n\nRaz ist über die Rampe auf der anderen Seite der Schmiede weggerannt. LOS, LOS, LOS!", sourceObjectiveStatus = "unverified-source-field" }
quests[28740] = { id = 28740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann ich meinen Augen trauen?", description = "<Ein lautes, mädchenhaftes Kreischen entweicht Pips Helm.>\n\nDAS KANN NICHT SEIN! Ich... Ich habe fast einen ganzen Monat in einem dieser Dinger festgesteckt. Ja, buchstäblich im Magen. Ohne meinen Anzug und meinen Allzwecktaucherhelm hätte mich ein feuriger Tod ereilt! Und schaut Euch das an, es hat Nachwuchs bekommen!\n\nI... Ihr müsst dieses Ding aufhalten, {name}! Wir dürfen nicht zulassen, dass es oder sein Nachwuchs hier lebendig hier rauskommen!", sourceObjective = "Tötet Bella", progress = "<Finkles Helm knistert vor statischer Aufladung.>", completion = "<Pips Helm gibt ein statisches Knistern von sich.>\n\nPuh... Eine Sache weniger, um die ich mir Sorgen machen muss, sollten wir es hier jemals rausschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28741] = { id = 28741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aszendentenfürst Obsidius", description = "<Pips Helm brummt.>\n\nMEINE GÜTE! Schaut Euch diesen Ort an! S... Sind das etwa Kratzspuren von Todesschwinge an der Decke?! Und was ist das für eine Kreatur da in der Mitte der Kammer?\n\nIch kann Raz nicht sehen. Kümmern wir uns um dieses Monster und finden Raz!", sourceObjective = "Tötet Aszendentenfürst Obsidius.", completion = "Armer Raz. Er war der beste Freund, den ein Gnom jemals hatte. Zumindest haben wir seinen Tod gerächt und diese höllischen Höhlen gesäubert!", sourceObjectiveStatus = "unverified-source-field" }
quests[28742] = { id = 28742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shy-Rotam", description = "Zeit für den großen Abschuss, Kumpel! Shy-Rotam schleicht im Norden umher - der größte Frostsäbler, den es gibt.\n\nIhr solltet Euch geehrt fühlen. Es gibt keine größere Herausforderung für einen Jäger... und wenn Ihr die Belohnung gesehen hättet, die mir von diversen Leckermäulern angeboten wurde, die ein Stück von diesem Kerl haben wollen, würden Euch die Augen ausfallen!\n\nSobald Ihr ihn erledigt habt, kommt zurück zum Lager. Ihr wollt unsere Frostsäblerpopulation schließlich nicht an einem Tag ausrotten...", sourceObjective = "Tötet Shy-Rotam.", completion = "Erstaunlich. Ihr seid einen Tick besser als die anderen! Ich bin habe ungefähr fünf verschiedene Vertragsjäger angeheuert, um diese Katze zu töten.\n\nNun, zwei von ihnen haben wir gefunden, nachdem der Hauptmann den Kadaver bekommen hatte, aber vertiefen wir das nicht weiter...", sourceObjectiveStatus = "unverified-source-field" }
quests[28743] = { id = 28743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heckschütze!", description = "Ist Euch nach ein wenig Jagen zumute, {name}?\n\nSteigt ein! Ich fliege, Ihr schießt!", sourceObjective = "Schießt 15 Fliegerasse von Schnottz ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[28744] = { id = 28744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghule hassen meine Saat", description = "Ihr seid ein Fachmann in dieser Sache, {name}! Ein regelrechter Aushilfsbotaniker! Hört, ich habe ein neues Saatgut auszutesten, das Felsnuss genannt wird. Verwendet es, um die Untoten zu blockieren. Werft es einfach auf den Boden und sie bleiben wie angewurzelt stehen. Untote sind so dämlich!\n\nVersuchen wir es!", sourceObjective = "Überlebt 2 riesige Zombiewellen.", completion = "Ich glaube, ich habe Stillwasser erzürnt. Jetzt fährt er die großen Geschütze auf. Keine Zeit zu verlieren, los geht's!", sourceObjectiveStatus = "unverified-source-field" }
quests[28745] = { id = 28745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmackhafte Kreischer", description = "Diese kleineren Eulen sind schon sehr lecker, aber Gutmampf sagt, es gibt weiter im Süden sogar noch größere! \"Kreischer\" werden sie von den Leuten aus der Gegend genannt. Sie machen ganz schön viel Lärm, wenn man sich mit ihnen prügelt. \n\nAber er sagt, es sind die besten Eulen, die er je gekostet oder verkauft hat und ich glaube ihm. Warum scheucht Ihr nicht ein paar von ihnen für uns auf und ich streite mich hier weiter mit Francis.", sourceObjective = "Tötet 15 Winterquellkreischer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28746] = { id = 28746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Verteidigung durchbrechen", description = "Los geht's, {name}!\n\nDirekt hinter dieser Tür liegt der Kontrollraum.\n\nIch renne einfach hinein, deaktiviere den Neuerschaffungsmechanismus und dann gehen wir alle wieder nach Hause. So einfach ist das.\n\nIhr werdet sehen, <Bursche/Mädel>, es ist diese hohe Kunst der Vorbereitung, die den wahren Archäologen von dem durchschnittlichen Jäger eines verlorenen Schatzes unterscheidet.\n\nEs ergibt keinen Sinn, die Bestien aufzumischen, wenn man's nicht muss. Man veranstaltet nur unnötig ein großes Durcheinander...", sourceObjective = "Verschafft Euch Zutritt zum Kontrollraum der Titanen.", progress = "Was gibt's, {name}?", completion = "Nun, ich habe eine schlechte Nachricht für Euch und eine...\n\nNein, streicht das. Ich habe nur schlechte Nachrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28747] = { id = 28747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kürbisbomben", description = "Habt Ihr so was schon mal gesehen?\n\n<Brazie zieht einen Kürbis heraus.>\n\nDies sind keine gewöhnlichen Kürbisse. Seht, sobald man sie einpflanzt, warten sie bis ein Zombie auftaucht und dann, KABUMM, fliegen die Zombies in Einzelteilen durch die Luft. Los geht's!", sourceObjective = "Überlebt 2 riesige Zombiewellen.", completion = "H... Habt Ihr das Rumpeln gehört? Ich glaube, Stillwasser kommt! Heiliger Strohsack, passt auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[28748] = { id = 28748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasen der lebenden Toten", description = "ES IST STILLWASSER! ER IST FAST HIER! Wir werden alles ins Rennen werfen müssen, was wir haben, um ihn zu schlagen. Auf geht's!", sourceObjective = "Besiegt Aufseher Stillwasser.", completion = "Ich kann nicht glauben, dass wir ihn besiegt haben, {name}! Das war der härteste Kampf, den wir bisher hatten, aber es gibt noch immer Hunderte von durchgeknallten Zombies, die im Hügelland ihr Unwesen treiben. Wir müssen auf der Hut bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28749] = { id = 28749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Andorhal", description = "Gerade ist ein Greif mit Neuigkeiten aus den Pestländern eingetroffen. Es klingt nicht gut.\n\nDie Stadt Andorhal befindet sich inmitten eines Krieges zwischen drei Fronten: die Verlassenen, die Allianz und die Geißel. König Wrynn hat eine Entscheidung getroffen und einen Todesritter geschickt, der seine Sache anführen soll, aber ich bin mir sicher, dass er jede Hilfe braucht, die er bekommen kann. \n\nDie Nachricht sagt ausdrücklich: \"{class} von der Allianz für besondere Einsätze gesucht\". Wenn Ihr die Herausforderung annehmt, sprecht wieder mit mir und ich werde ein Portal beschwören.", sourceObjective = "Sprecht mit Kriegsmagier Erallier, um nach Andorhal in den Westlichen Pestländern teleportiert zu werden. Dann meldet Euch bei Thassarian in Andorhal.", completion = "Es wurde Zeit, dass Ihr kommt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28750] = { id = 28750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Andorhal", description = "Gerade ist ein Windreiter mit Neuigkeiten aus den Pestländern eingetroffen. Es klingt nicht gut.\n\nDie Stadt Andorhal ist in der Mitte eines Krieges zwischen drei Fronten: die Verlassenen, die Allianz und die Geißel. Es klingt so, als ob Sylvana eine Entscheidung getroffen hat und um es noch interessanter zu machen, hat sie dem Todesritter Koltira Todesweber das Kommando übertragen.\n\nDie Nachricht sagt ausdrücklich: \"{class} von der Horde für besondere Einsätze gesucht\". Wenn Ihr die Herausforderung annehmt, sprecht wieder mit mir und ich werde ein Portal beschwören.", sourceObjective = "Sprecht mit Arkanist Arman, um nach Andorhal in den Westlichen Pestländern teleportiert zu werden. Dann meldet Euch bei Koltira Todesweber in Andorhal.", completion = "Es wurde Zeit, dass Ihr kommt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28751] = { id = 28751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unkraut jäten", description = "Obwohl wir Aufseher Stillwasser geschlagen haben, streifen seine Zombies noch immer durch die Gegend. Seht dort, eine neue Welle nähert sich uns! Helft mir, sie zurückzuschlagen, Kumpel! Los geht's!", sourceObjective = "Überlebt 2 riesige Zombiewellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28752] = { id = 28752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unaufhaltsamer Ansturm", description = "Seht, wie lange Ihr durchhaltet! Übersteht mindestens 10 Anstürme und ich gebe Euch ein paar Münzen." }
quests[28753] = { id = 28753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die harte Tour", description = "So ein verdammter Mist!\n\nJemand hat das gesamte System zum Absturz gebracht! Ich kann von dieser Konsole überhaupt nicht mehr auf den Hauptspeicher zugreifen.\n\nWir werden es auf die harte Tour machen müssen, <Kumpel/Mädel>. Ich hoffe, Ihr und Eure Freunde hier haben Lust auf einen Kampf.\n\nEs gibt vier Wächter auf den oberen Ebenen dieser Anlage. Ich werde nicht in der Lage sein, diese Scheiben zu verwenden, bis sie... ähm, sagen wir mal abgeschaltet sind.", sourceObjective = "Brann Bronzebart will, dass Ihr Isiset, Ammunae, Setesh und Rajh tötet.", completion = "Aaalso gut.\n\nDeponieren wir diese Scheiben und das war's dann!", sourceObjectiveStatus = "unverified-source-field" }
quests[28755] = { id = 28755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Annalen der Silbernen Hand", description = "Wisst Ihr, wer die Ritter der Silbernen Hand waren? Es waren die ursprünglichen Paladine des Lichts und aus ihren Reihen stammten die Ritter, die später der Argentumdämmerung oder den Scharlachroten Kreuzfahrern beitraten. Obwohl viele vom Weg abgekommen sind, besitzen sie noch immer wertvolle Relikte der Silbernen Hand.\n\nTief in Stratholme unter den wachsamen Augen von Archivar Galford haben Bände der Annalen der Silbernen Hand die Zeiten überdauert. Jeder Band, den Ihr auftreiben könnt, wäre eine passende Ergänzung für die umgewidmete Kapelle des Hoffnungsvollen Lichts.", sourceObjective = "Treibt einen verschollenen Band der Annalen der Silbernen Hand in Stratholme auf.", progress = "Konntet Ihr die verschollenen Aufzeichnungen der Silbernen Hand ausfindig machen?", completion = "Dies ist tatsächlich einer der verschollenen Bände! Tyrosus wird hocherfreut sein, wenn er von Eurem Fund erfährt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28756] = { id = 28756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entartung des Knochens", description = "Im Leben kämpften meine Brüder und ich gegen all die Kräfte der Geißel, aber niemand war so schändlich wie die Totenbeschwörer. Es hat ihnen nicht gereicht, unsere toten Kameraden auferstehen zu lassen und sie gegen uns kämpfen zu lassen, nein, sie erschufen perverse Golems aus Knochen mit Sicheln statt Händen.\n\nDiese Entartungen töteten viele meiner Brüder und dennoch konnten sie nicht alle vernichten. Ich bitte Euch, {name}, die Aufgabe der Gefallenen fortzuführen. Reist in das Ossuarium von Scholomance und vernichtet die größte und gefährlichste dieser scheußlichen Kreaturen.", sourceObjective = "Tötet Blutrippe im Ossuarium von Scholomance.", completion = "Eure Taten ehren diejenigen, die bei der Verteidigung dieses heiligen Bodens gefallen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28757] = { id = 28757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt sie zurück!", description = "Ihr seid also der neue Rekrut aus Sturmwind, wie? Ich bin Marschall McBride, Kommandant dieser Garnison. Ich bin froh, Euch an Bord zu haben...\n\n<McBride sieht ein paar Zettel durch.>\n\n{name}. Ihr seid {name}, ja?\n\nIhr seid genau zur rechten Zeit gekommen. Die Schwarzfelsorcs haben es geschafft, sich durch einen Felsspalt in den Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzuschlagen, aber ich fürchte, sie werden bald übermannt werden.\n\nBegebt Euch nach Nordwesten in den Wald und tötet die angreifenden Worgs des Schwarzfels! Helft meinen Soldaten!", sourceObjective = "Tötet 6 Kampfworgs des Schwarzfels.", completion = "Ihr habt uns ein wenig Zeit verschafft, {name}, aber wir haben jetzt ein noch größeres Problem, um das wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28758] = { id = 28758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf um Leben und Tod", description = "Todesschwinge und Alexstrasza haben sich in den Himmel über Grim Batol erhoben! Ihr Plan droht zu scheitern - die Königin der Drachen ist außerhalb des Kreises des Lebens, den sie zuvor eingerichtet hat. Wir werden sie mit allem unterstützen müssen, was wir haben.\n\nBeeilung! Steigt auf einen der Zinnoberroten Vorposten hinter mir.\n\nWenn wir auf irgendwelche Zwielichtdrachen treffen, die Todesschwinge helfen, werden wir sie töten müssen. Sitzt auf, schnell!", sourceObjective = "Steigt auf einen Zinnoberroten Vorposten. Tötet 8 Zwielichtschattendrachen.", completion = "Dank Eures schnellen Handelns lebt die Königin der Drachen noch. Sie wird zurück zum Wyrmruhtempel gebracht, um sich zu erholen.\n\nAber die Schlacht war kein vollständiger Fehlschlag. Todesschwinge ist schwer verwundet. Ich vermute, er wird sich verstecken, um zu Kräften zu kommen. Alexstrasza hat uns Zeit verschafft, um zuzuschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28759] = { id = 28759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgs im Schafspelz", description = "Die einfallenden Orcs sind keine Narren. Sie schätzen uns ab, stellen sicher, dass ihre Angriffe zu ihrem Vorteil sein werden.\n\nIm Wald nordwestlich sind Spione der Schwarzfelsorcs. Sie spähen uns durch Handfernrohre aus, überwachen jeden unserer Schritte - und warten. Ich will, dass Ihr sie angreift!\n\nTötet die Spione der Schwarzfelsorcs! Wir müssen ihnen zeigen, dass wir wissen, dass sie uns beobachten und dass wir vorbereitet sind!", sourceObjective = "Tötet 8 Spione des Schwarzfels.", completion = "Hervorragende Arbeit, {name}. Es hat sich herausgestellt, dass Ihr ein echter Gewinn für die Garnison seid. Es wird Zeit für Eure Ausbildung!", sourceObjectiveStatus = "unverified-source-field" }
quests[28760] = { id = 28760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für Orsis", description = "Die große Stadt Orsis wurde von den Armeen der Lüfte angegriffen.\n\nWir wurden gefangen genommen. Und dabei waren wir noch diejenigen, die Glück hatten.\n\nDie meisten starben, begraben unter dem schweren Wüstensand.\n\nAl'Akirs Kalif Asaad hat den Angriff befohlen... und dafür soll er mit dem Leben bezahlen.", sourceObjective = "Tötet Asaad.", completion = "Seid gesegnet. Bitte nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28762] = { id = 28762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt sie zurück!", description = "Ihr seid also der neue Rekrut aus Sturmwind, wie? Ich bin Marschall McBride, Kommandant dieser Garnison. Ich bin froh, Euch an Bord zu haben...\n\n<McBride sieht ein paar Zettel durch.>\n\n{name}. Ihr seid {name}, ja?\n\nIhr seid genau zur rechten Zeit gekommen. Die Schwarzfelsorcs haben es geschafft, sich durch einen Felsspalt in den Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzuschlagen, aber ich fürchte, sie werden bald übermannt werden.\n\nBegebt Euch nach Nordwesten in den Wald und tötet die angreifenden Worgs des Schwarzfels! Helft meinen Soldaten!", sourceObjective = "Tötet 6 Kampfworgs des Schwarzfels.", completion = "Ihr habt uns ein wenig Zeit verschafft, {name}, aber wir haben jetzt ein noch größeres Problem, um das wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28763] = { id = 28763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt sie zurück!", description = "Ihr seid also der neue Rekrut aus Sturmwind, wie? Ich bin Marschall McBride, Kommandant dieser Garnison. Ich bin froh, Euch an Bord zu haben...\n\n<McBride sieht ein paar Zettel durch.>\n\n{name}. Ihr seid {name}, ja?\n\nIhr seid genau zur rechten Zeit gekommen. Die Schwarzfelsorcs haben es geschafft, sich durch einen Spalt im Felsen in den Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzuschlagen, aber ich fürchte, sie werden bald übermannt werden.\n\nBegebt Euch nach Nordwesten in den Wald und tötet die angreifenden Schwarzfelsworgs! Helft meinen Soldaten!", sourceObjective = "Tötet 6 Kampfworgs des Schwarzfels.", progress = "Habt Ihr die Kampfworgs des Schwarzfels zurückgeschlagen?", completion = "Ihr habt uns ein wenig Zeit verschafft, {name}, aber wir haben jetzt ein noch größeres Problem, um das wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
