quests[28768] = { id = 28768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterquell!", description = "Die Zwergenfrau Donova Schneeweh ist mit dem Furbolgs der Holzschlundfeste befreundet.\n\nWir handeln mit Feuerwasser.\n\nSie ist bei den Frostfeuerquellen im Westen, wenn Ihr durch unsere Höhle geht.\n\nSie braucht Unterstützung beim Verprügeln der Furbolgs der Winterfelle. Vielleicht könnt Ihr ihr helfen.", sourceObjective = "Meldet Euch bei Donova Schneeweh an den Frostfeuerquellen in Winterquell.", completion = "Dem Licht sei Dank, dass Ihr hier seid. Ich habe das Geheimnis der grimmigen Furbolgs der Winterfelle aufgedeckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28769] = { id = 28769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgs im Schafspelz", description = "Die einfallenden Orcs sind keine Narren. Sie schätzen uns ab, stellen sicher, dass ihre Angriffe zu ihrem Vorteil sein werden.\n\nIm Wald nordwestlich von hier lauern Spione der Schwarzfelsorcs. Sie kundschaften uns mit ihren Handfernrohren aus, überwachen jeden unserer Schritte - und warten. Ich will, dass Ihr sie angreift!\n\nTötet die Spione der Schwarzfelsorcs! Wir müssen ihnen zeigen, dass wir sehr wohl wissen, dass sie uns beobachten und dass wir vorbereitet sind!", sourceObjective = "Tötet 8 Spione der Schwarzfelsorcs.", completion = "Hervorragende Arbeit, {name}. Es hat sich herausgestellt, dass Ihr ein echter Gewinn für die Garnison seid. Es wird Zeit für Eure Ausbildung!", sourceObjectiveStatus = "unverified-source-field" }
