quests[28775] = { id = 28775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrochene Schlangenfigur", description = "Diese zerbrochene Figur wurde von ihrem ehemaligen Besitzer fortgeworfen. Mit den richtigen Materialien und Euren Fertigkeiten in der Juwelierskunst könntet Ihr sie jedoch vollständig reparieren.", sourceObjective = "Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.", sourceObjectiveStatus = "unverified-source-field" }
quests[28776] = { id = 28776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrochene Figur eines Irdenen", description = "Diese zerbrochene Figur wurde von ihrem ehemaligen Besitzer fortgeworfen. Mit den richtigen Materialien und Euren Fertigkeiten in der Juwelierskunst könntet Ihr sie jedoch vollständig reparieren.", sourceObjective = "Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.", sourceObjectiveStatus = "unverified-source-field" }
quests[28777] = { id = 28777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschädigte Figur einer Eule", description = "Diese zerbrochene Figur wurde von ihrem ehemaligen Besitzer fortgeworfen. Mit den richtigen Materialien und Euren Fertigkeiten in der Juwelierskunst könntet Ihr sie jedoch vollständig reparieren.", sourceObjective = "Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.", sourceObjectiveStatus = "unverified-source-field" }
quests[28778] = { id = 28778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrochene Figur eines Keilers", description = "Diese zerbrochene Figur wurde von ihrem ehemaligen Besitzer fortgeworfen. Mit den richtigen Materialien und Euren Fertigkeiten in der Juwelierskunst könntet Ihr sie jedoch vollständig reparieren.", sourceObjective = "Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.", sourceObjectiveStatus = "unverified-source-field" }
quests[28779] = { id = 28779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weit von zuhause entfernt", description = "Ich habe das Gefühl, dass man mich hat fliehen lassen, weil ich hier ohnehin nicht fort kann.\n\nIch sitze auf diesen Plattformen fest und deshalb finden sie mich früher oder später sowieso. Es sei denn...\n\nMan sagt, das Herz eines Elementarfürsten übertrüge demjenigen, der es in Händen hält, die Eigenschaften des jeweiligen Elements. Im Falle von Luft wäre das für eine Reise hinab äußerst nützlich.\n\nBringt mir das Herz von Großwesir Ertan, sodass ich mithilfe seiner Magie sicher an der Küste von Uldum landen kann.", sourceObjective = "Beschafft das Herz von Großwesir Ertan.", progress = "Ihr solltet mir besser nicht anbieten, mit Euch zu reiten... was auch immer das für ein Ding ist, auf dem Ihr hierhergeflogen seid.", completion = "Ich danke Euch, {name}. Selbst nach meiner Flucht habe ich nicht ernsthaft zu hoffen gewagt, einst nach Hause zurückzukehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28780] = { id = 28780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stürzt Euch in die Schlacht!", description = "Während Ihr unterwegs wart, um zu trainieren, habe ich eine dringliche Nachricht von Stellvertreter Willem erhalten. Wie sich herausstellt, haben die Schwarzfelsorcs goblinische Auftragsmörder angeheuert. Sie haben unser Bataillon hinter der Abtei aus dem Hinterhalt angegriffen. Willem bat mich, ihm einen Helden zu schicken. Ihr müsst ihnen helfen, {name}!\n\nFindet Stellvertreter Willem nördlich der Abtei am Kommandozelt. Geht!", sourceObjective = "Meldet Euch bei Stellvertreter Willem hinter der Abtei von Nordhain im Wald von Elwynn.", completion = "Es stimmt, man hat uns aus dem Hinterhalt angegriffen. Ich wage es nicht, noch weitere Soldaten dort hinauszuschicken und zu riskieren, sie auch noch zu verlieren. Ich brauche einen Freiwilligen. Jemanden, der bereit ist, sein Leben zu riskieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[28781] = { id = 28781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelegenheitsziele", description = "Wir waren Teil einer verdeckten Operation, die Prinz Nadun von Ramkahen eingefädelt hat. Wir haben die meisten unserer Einheiten in einem Hinterhalt verloren und wir sind jetzt nicht mehr in der Lage, unsere Mission abzuschließen.\n\nFalls es für Euch eine Rolle spielt, kann ich Euch zu einer ansehnlichen Belohnung verhelfen.\n\nUns wurde aufgetragen, jedes sich bietende Ziel auszuschalten, das für die militärische Infrastruktur der Feinde von Bedeutung ist.\n\nWir haben General Husam ausfindig gemacht und zwei seiner Hauptmänner. Wenn Ihr sie für uns tötet, würdet Ihr Ramkahen einen großen Dienst erweisen.", sourceObjective = "Tötet General Husam und 2 eingeschworene Hauptmänner.", progress = "Ist es vollbracht, {name}?", completion = "Hervorragende Arbeit, {name}. Ihr werdet Eurem Ruf gerecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28782] = { id = 28782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein legendärer Vogel", description = "Die einheimischen Legenden berichten von einer riesenhaften Eule, die über den Berggipfeln kreist wie der geflügelte Tod. Man nannte sie Todesschwinge.\n\nKurz darauf erfuhr man, dass der Name bereits vergeben war. Also entschied man sich für einen Ersatznamen, der ebenfalls Furcht und Schrecken verbreiten sollte:\n\nHöllenschuhu.\n\nHöllenschuhu ist auf dem Berggipfel südwestlich unserer Räuchergrube anzutreffen. Bringt dieses teuflische Nachttier zum Schweigen... damit wir es essen können!", sourceObjective = "Tötet Höllenschuhu.", completion = "Höllenschuhu ist besiegt und Ihr Fleisch ist tatsächlich so wohlschmeckend, wie wir es uns gedacht haben.\n\nHeute verspeisen wir eine Legende. Habt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28783] = { id = 28783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle ihrer Macht", description = "Bevor unsere Truppe in den Hinterhalt geriet, haben wir es noch geschafft, den Gegner auszuspionieren. \n\nWir haben herausgefunden, dass Siamat, der Gesandte von Todesschwinge, den Neferset ihre neue Kraft verleiht.\n\nSie haben behauptet, er hätte ihnen wieder zu alter Größe verholfen, aber es ist noch etwas anderes geschehen. Ihre Seelen wurden verdorben.\n\nAls einer der vier Winde ist Siamat unglaublich mächtig. Aber dieser Prozess hat ihn einiges seiner Kraft gekostet.\n\nSchlagt jetzt zu, während es noch möglich ist, ihn zu vernichten und bereitet diesem Wahnsinn ein Ende.", sourceObjective = "Tötet Siamat.", completion = "Es stimmt also? Die große Seuche, die unser Volk befallen hat, hat bald ein Ende, jetzt, wo die Neferset ihre Fähigkeit verloren haben, unser Volk noch weiter zu korrumpieren.\n\nNennt Euren Preis, {class}. Das ist das Mindeste, was wir für Euch tun können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28784] = { id = 28784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stürzt Euch in die Schlacht!", description = "Während Ihr unterwegs wart, um zu trainieren, habe ich eine dringliche Nachricht von Stellvertreter Willem erhalten. Wie sich herausstellt, haben die Schwarzfelsorcs goblinische Auftragsmörder angeheuert. Sie haben unser Bataillon hinter der Abtei aus dem Hinterhalt angegriffen. Willem bat mich, ihm einen Helden zu schicken. Ihr müsst ihnen helfen, {name}!\n\nFindet Stellvertreter Willem nördlich der Abtei am Kommandozelt. Geht!", sourceObjective = "Meldet Euch bei Stellvertreter Willem hinter der Abtei von Nordhain im Wald von Elwynn.", completion = "Es stimmt, man hat uns aus dem Hinterhalt angegriffen. Ich wage es nicht, noch weitere Soldaten dort hinauszuschicken und zu riskieren, sie auch noch zu verlieren. Ich brauche einen Freiwilligen. Jemanden, der bereit ist, sein Leben zu riskieren!", sourceObjectiveStatus = "unverified-source-field" }
