quests[28794] = { id = 28794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben Auftragsmörder losgeschickt", description = "Habt Ihr jemals einen Goblin gesehen, {name}? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", sourceObjective = "Tötet 8 goblinische Auftragsmörder.", completion = "Ihr habt diesen Monstern eine Lektion erteilt! Sie werden es sich zweimal überlegen, bevor sie noch einen Mordauftrag der Orcs annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28795] = { id = 28795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben Auftragsmörder losgeschickt", description = "Habt Ihr jemals einen Goblin gesehen, {name}? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", sourceObjective = "Tötet 8 goblinische Auftragsmörder.", completion = "Ihr habt diesen Monstern eine Lektion erteilt! Sie werden es sich zweimal überlegen, bevor sie noch einen Mordauftrag der Orcs annehmen.", sourceObjectiveStatus = "unverified-source-field" }
