quests[28797] = { id = 28797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben Auftragsmörder losgeschickt", description = "Habt Ihr jemals einen Goblin gesehen, {name}? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", sourceObjective = "Tötet 8 goblinische Auftragsmörder.", completion = "Ihr habt diesen Monstern eine Lektion erteilt! Sie werden es sich zweimal überlegen, bevor sie noch einen Mordauftrag der Orcs annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28798] = { id = 28798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Wasser", progress = "Ihr habt einen ungewöhnlichen Brunnen entdeckt. Das Wasser leuchtet wie Mondlicht und gibt weiche, summende Töne von sich. Mit einer Hochgeborenenschriftrolle und Euren eindrucksvollen, archäologischen Fähigkeiten, könntet Ihr den Zweck dieses Brunnens entschlüsseln.", completion = "Nach ein paar Augenblicken seid Ihr in der Lage, mithilfe des Schlüsselsteins das Geheimnis des Wassers zu enthüllen..." }
quests[28799] = { id = 28799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Irdenen", progress = "Auf den ersten Blick erscheint dieser Pfeiler sehr unbedeutend, aber dank Eurer Archäologiekenntnisse wisst Ihr, dass dem nicht so ist. Wenn Ihr einen Zwergenrunenstein hättet, könnte sein Ursprung ans Licht gebracht werden.", completion = "Aha! Ihr wusstet, dass Ihr diesem Grad meisterlichen Handwerks schon zuvor begegnet seid. Jetzt, mit dem letzten Teil..." }
quests[28800] = { id = 28800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Flüstern des Djinns", progress = "Diese Kohlenpfanne ist offensichtlich magisch, aber sie scheint nicht empfänglich für Eure Versuche, ihre Kräfte zu entfesseln. Wenn Ihr nur einen Schlüsselstein für Tol'vir-Hieroglyphen zur Verfügung hättet, könntet Ihr damit die Steingravuren an ihrer Seite entschlüsseln.", completion = "Es scheint, als ob in dieser speziellen Kohlenpfanne ein niederer Djinn gefangen gehalten wird. Ihn zu befreien würde sicherlich eine Belohnung mit sich bringen. Oder?" }
quests[28801] = { id = 28801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hieroglyphen der Tol'vir", progress = "Dieser Grabstein markiert eine seltsame Grabstätte – vermutlich von einem der ursprünglichen Erbauer. Wenn Ihr Tol'vir Hieroglyphen zur Verfügung hättet, könnten sie Euch helfen, den Text zu verstehen. Dies könnte sich als bedeutender, archäologischer Fund erweisen!", completion = "Mithilfe des Schlüsselsteins findet Ihr heraus, dass dies das Grab eines der ursprünglichen Erbauer ist. Ihr habt wichtige Details über den Mumifizierungsprozess erfahren." }
quests[28802] = { id = 28802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Karte der Architekten" }
quests[28803] = { id = 28803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache der Wildhämmer", progress = "Diese alten Knochen scheinen zwergisch zu sein. Eventuell stammen sie von den ursprünglichen Erbauern von Grim Batol. Möglicherweise findet Ihr beim Vergleich der Zeichen auf der steinernen Gürtelschnalle mit einem Zwergenrunenstein mehr über Euren Fund heraus.", completion = "Nachdem Ihr beides sorgfältig miteinander verglichen habt, seid Ihr Euch sicher, dass dies die Überreste eines Wildhammerzwergs sind. Der Verrat, der gegen sie begangen wurde, erfüllt Euer Herz mit Wut." }
quests[28804] = { id = 28804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausweichplan der Dunkeleisenzwerge", progress = "Dies sind definitiv Pläne irgendeiner Art, aber wofür könnt Ihr nicht sicher sagen. Sie sind mit charakteristischen Zeichen versehen, die mit denen eines Zwergenrunensteins verglichen werden können.", completion = "Interessant! Es scheint, als hätten die Dunkeleisenzwerge eine Strategie für den Fall entwickelt, dass sie einer Invasion von Elementaren gegenüberstehen würden. Da Elementarkräfte unveränderlich sind und nicht altern, scheint es, als ob diese uralten Techniken auch noch heute anwendbar sind." }
quests[28805] = { id = 28805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge des Sturms", description = "Seid gegrüßt, {name}!\n\nJa, Euer Name ist dem Irdenen Ring nicht unbekannt.\n\nDie Zahl Eurer Heldentaten und Errungenschaften ist Legion. Azeroth steht schon jetzt tief in Eurer Schuld und dennoch bedarf das Land erneut seiner Helden.\n\nIch bin nur ein Bote. Eine bekannte Präsenz wünscht mit Euch zu sprechen.\n\nSchaut in die Wasser der Weitsicht und sehet das Schicksal unserer Welt.", sourceObjective = "Scharfseher Krogar will, dass Ihr in die Wasser der Weitsicht schaut.", progress = "Ja, {class}?", completion = "Jetzt, wo Ihr die Wahrheit gesehen habt, werdet Ihr Euch dazu entschließen zu dienen?", sourceObjectiveStatus = "unverified-source-field" }
quests[28806] = { id = 28806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürchtet nicht das Böse", description = "Habt Ihr Euch schon zum Heiligen Licht bekannt, <Bruder/Schwester>? Durch das Heilige Licht werden wir errettet! Das Heilige Licht versetzt mich in die Lage, diese überaus fordernden Soldaten zu heilen! Und durch das Heilige Licht werdet Ihr in der Lage sein, hinaus ins Feld nach Norden zu gehen, und unsere gefallenen Brüder zu retten!\n\nTragt dieses Gebetsbuch mit Euch ins Feld und wirkt die heilende Berührung des Lichts auf die Verwundeten.", sourceObjective = "Belebt 4 verletzte Soldaten von Sturmwind wieder.", completion = "Ich glaube, Ihr versteht nun, welche Macht dem Licht innewohnt. Das Licht spendet Hoffnung, Bruder, und das Licht lässt die Finsternis schwinden! GESEGNET SEI DAS LICHT!", sourceObjectiveStatus = "unverified-source-field" }
quests[28807] = { id = 28807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Meinung des Spezialisten", description = "<Anduin hält die zueinanderpassenden Abzeichen hoch.> \n\nDas Medaillon, das wir auf dem Hof gefunden haben, ist identisch mit dem in Samuelsons Aufzeichnungen! Das kann kein Zufall sein. Ich glaube, Samuelson hat etwas vor, aber wir brauchen einen schlagenden Beweis, bevor wir einen Wächter beschuldigen, der das höchste Vertrauen meines Vaters genießt.\n\nEs gibt nur eine Person, der ich zutraue, dies alles wieder einzurenken: Mathias Shaw, der Anführer von SI:7. Zeigt ihm diese Abzeichen und wir sehen, was er darüber denkt. In der Zwischenzeit werde ich mich ebenfalls zurück zur Burg Sturmwind begeben und werde dort Samuelson keine Sekunde aus den Augen lassen!", sourceObjective = "Bringt die verdächtigen Abzeichen zu Mathias Shaw im SI:7 Hautquartier in Sturmwind.", progress = "Was habt Ihr mir da mitgebracht?", completion = "Anduin stellt Nachforschungen über den Schattenhammer an? Solltet Ihr nicht dafür sorgen, dass er NICHT in Schwierigkeiten gerät?\n\nHmmm. Lasst mich diese Abzeichen sehen, die Ihr entdeckt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28808] = { id = 28808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürchtet nicht das Böse", description = "Habt Ihr Euch schon zum Heiligen Licht bekannt, <Bruder/Schwester>? Durch das Heilige Licht werden wir errettet! Das Heilige Licht versetzt mich in die Lage, diese überaus fordernden Soldaten zu heilen! Und durch das Heilige Licht werdet Ihr in der Lage sein, hinaus ins Feld nach Norden zu gehen, und unsere gefallenen Brüder zu retten!\n\nTragt dieses Gebetsbuch mit Euch ins Feld und wirkt die heilende Berührung des Lichts auf die Verwundeten.", sourceObjective = "Belebt 4 verletzte Soldaten von Sturmwind wieder.", completion = "Ich glaube, Ihr versteht nun, welche Macht dem Licht innewohnt. Das Licht spendet Hoffnung, Schwester, und das Licht lässt die Finsternis schwinden! GESEGNET SEI DAS LICHT!", sourceObjectiveStatus = "unverified-source-field" }
