quests[28814] = { id = 28814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Anführerin und ihre Anhänger", description = "Die Dokumente beschreiben die genauen Umstände der Ankunft von Hohepriesterin Azil in den Tiefen des Steinernen Kerns.\n\nAzil wird als ein hochrangiges Mitglied des Zwielichtrates beschrieben. Darüber hinaus bereitet ihre Gefolgschaft aus über hundert ergebenen Anhängern ein schreckliches Ritual von unvorhersehbarer Finsternis vor.\n\nKlingt wie ein Ereignis, das Ihr abwenden müsst.", sourceObjective = "Vernichtet Hohepriesterin Azil und 101 ihrer ergebenen Anhänger.", progress = "Ihr seid zurückgekehrt, {name}. Welche Neuigkeiten bringt Ihr?", completion = "Eine Hohepriesterin sagt Ihr? Und ein Mitglied des Zwielichtrates?\n\nAusgezeichnete Arbeit. Ich hoffe, Ihr empfindet Eure Belohnung als angemessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28815] = { id = 28815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokumente des Schattenhammers", description = "Wir sind einem der Schattenhammeragenten bis hierher gefolgt. Er trägt den Namen Millhaus Manasturm.\n\nWir haben Grund zu der Annahme, dass er wichtige Dokumente bei sich trägt.\n\nBis zu diesem Punkt können wir gehen, ohne unsere Pflicht zu verletzen, den innersten Teil des Tempels der Erde zu verteidigen.\n\nFindet Manasturm und holt Euch die Dokumente von ihm.", sourceObjective = "Beschafft die Dokumente des Schattenhammers.", progress = "Dies scheinen die richtigen Dokumente zu sein.", completion = "<Ihr öffnet die Dokumente und durchsucht sie nach bedeutsamen Informationen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28816] = { id = 28816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Tiefe", description = "Der Irdene Ring hat die wasserreichen Gefilde von Vashj'ir als Quelle zerstörerischer Energien des Feindes ausgemacht.\n\nEs ist noch immer unklar, mit welchen Gefahren wir es hier zu tun haben. Jegliche Informationen, die Ihr sammeln könnt, sind von großem Wert.\n\nDie Horde schickt in diesem Augenblick Kriegsschiffe in die Region. Um dorthin zu gelangen, sprecht mit Kommandant Thorak in der Messerbucht.\n\nMögen die Geister Euch leiten, {name}.", sourceObjective = "Meldet Euch bei Kommandant Thorak in der Messerbucht in Durotar.", completion = "Lok'tar, Bruder! Ihr kommt gerade zur rechten Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28817] = { id = 28817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr gebannt", description = "Ausgezeichnete Arbeit, {name}! Sie werden uns definitiv nicht mehr in den Rücken fallen. Wir kümmern uns um die Nachzügler. Ich will, dass Ihr zurück zu Marschall McBride geht, der südlich von hier vor der Abtei von Nordhain steht. Lasst ihn wissen, dass die Situation mit den Goblins unter Kontrolle ist.\n\nLebt wohl, {class}.", sourceObjective = "Meldet Euch bei Marschall McBride vor der Abtei von Nordhain im Wald von Elwynn.", completion = "Dank Eurer Hilfe ist es uns gelungen, die nördlichen und westlichen Abschnitte von Nordhain zu sichern. Dennoch gibt es im Osten noch immer eine ziemlich große Ansammlung von Schwarzfeslorcs und sie haben damit begonnen, den Wald niederzubrennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28818] = { id = 28818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr gebannt", description = "Ausgezeichnete Arbeit, {name}! Sie werden uns definitiv nicht mehr in den Rücken fallen. Wir kümmern uns um die Nachzügler. Ich will, dass Ihr zurück zu Marschall McBride geht, der südlich von hier vor der Abtei von Nordhain steht. Lasst ihn wissen, dass die Situation mit den Goblins unter Kontrolle ist.\n\nLebt wohl, {class}.", sourceObjective = "Meldet Euch bei Marschall McBride vor der Abtei von Nordhain im Wald von Elwynn.", completion = "Dank Eurer Hilfe ist es uns gelungen, die nördlichen und westlichen Abschnitte von Nordhain zu sichern. Dennoch gibt es im Osten noch immer eine ziemlich große Ansammlung von Schwarzfeslorcs und sie haben damit begonnen, den Wald niederzubrennen!", sourceObjectiveStatus = "unverified-source-field" }
