quests[28824] = { id = 28824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorener Sohn", description = "Eins meiner Kinder ist nicht bei mir, {name}.\n\nEr ist bei den Schattenhammerkultisten im Steinernen Kern im Tempel der Erde zurückgeblieben.\n\nIch habe meine anderen Kinder losgeschickt, um ihn von der finsteren Magie zu befreien, die ihn davon abhält, hierher zurückzukehren... Aber es wirkt keine Magie auf ihn ein.\n\nGeht in den Steinernen Kern und vernichtet Ozruk. Er muss zurück zur Erde aus der er gekommen ist.", sourceObjective = "Vernichtet Ozruk.", progress = "Ist es vollbracht, {race}?", completion = "<Therazanes Augen erscheinen etwas kristalliner, als es Euch in Erinnerung ist.>\n\nOzruk ist nun wieder Teil der Erde, aus der er gekommen ist.\n\nNehmt Eure Belohnung entgegen und geht wieder, {name}. Ich wünsche, alleine gelassen zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28825] = { id = 28825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine persönliche Einladung", description = "<Ein ungewohntes Gefühl steigt in Euch auf und überflutet Euren Geist mit Gedanken und Bildern.>\n\nHöret meine Worte, {name}.\n\nEine fürchterliche Krise hält unsere Welt fest in ihrem Griff. \n\nIch rufe Euch an, uns in dieser verzweifelten Stunde Hilfe zu leisten.\n\nIch bin Naraat.\n\nSucht mich umgehend auf und Eure Berufung wird sich enthüllen.\n\nIch erwarte Euch am Östlichen Erdschrein in Sturmwind.", sourceObjective = "Sprecht mit Naraat dem Erdsprecher in Sturmwind.", completion = "Möge Euer Sinn für Ehre und Pflicht Azeroth gute Dienste leisten, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28826] = { id = 28826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge des Sturms", description = "Seid gegrüßt, Held von Azeroth.\n\nIm Namen des Irdenen Rings danke ich Euch, dass Ihr meinem Ruf gefolgt seid.\n\nEuer Name ist uns nicht unbekannt, {name}.\n\nDie Zahl Eurer Heldentaten und Errungenschaften ist Legion. Azeroth steht schon jetzt tief in Eurer Schuld und dennoch bedarf das Land erneut seiner Helden.\n\nIch bin nur ein Bote. Eine mächtige Präsenz wünscht mit Euch zu sprechen.\n\nSchaut in die Wasser der Weitsicht und sehet, in welcher Zwangslage sich unserer Welt befindet.", sourceObjective = "Naraat der Erdsprecher will, dass Ihr in die Wasser der Weitsicht schaut.", progress = "Ja, {class}?", completion = "Jetzt, da Ihr die Wahrheit gesehen habt, werdet Ihr Euch dazu entschließen zu dienen?", sourceObjectiveStatus = "unverified-source-field" }
quests[28827] = { id = 28827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Tiefe", description = "Der Irdene Ring hat die wasserreichen Gefilde von Vashj'ir als Quelle zerstörerischer Energien des Feindes ausgemacht.\n\nEs ist noch immer unklar, mit welchen Gefahren wir es hier zu tun haben. Jegliche Informationen, die Ihr sammeln könnt, sind von großem Wert.\n\nDie Allianz schickt in diesem Augenblick Kriegsschiffe in die Region. Um dorthin zu gelangen, begebt Euch in den Nordwesten Sturmwinds und sprecht mit Rekrutierer Burns im Hafen von Sturmwind.\n\nMögen die Geister Euch leiten, {name}.", sourceObjective = "Sprecht mit Rekrutierer Burns im Hafen von Sturmwind in Sturmwind.", completion = "Alle unsere Kriegsschiffe sind in See gestochen, um gegen die Horde zu kämpfen. Ihr werdet das Söldnerschiff nehmen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28828] = { id = 28828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die richtigen Eier", description = "Ich habe keinen sehr anspruchsvollen Gaumen, aber selbst ich kann den Geschmack dieser Schimären nicht ertragen, die man in dieser Gegend findet. Ihre Eier sind dagegen etwas ganz anderes.\n\nSchimäreneier sind die reichhaltigsten, butterigsten Eier diesseits von Orgrimmar. Viel besser als langweilige Euleneier und nicht so schwefelhaltig wie diese merkwürdigen Wildekineier.\n\nIch nehme Euch so viele davon ab, wie Ihr sammeln könnt. Begebt Euch nach Norden und haltet nach ihren Nestern im Schnee Ausschau.", sourceObjective = "Treibt 40 Eiswindeier auf.", progress = "Mmmm...", completion = "Schön. Eier.\n\nDie passen wunderbar zu einem kleinen Bärenschinken. Hey, Francis, ist noch Bärenfleisch da?", sourceObjectiveStatus = "unverified-source-field" }
quests[28829] = { id = 28829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasiermesserscharfe Schnäbel", description = "Ihr fragt, was mir zugestoßen ist? Hört zu, {class} und zwar gut, denn meine Geschichte beschreibt eine echte Tragödie...\n\nIch wurde hierher ins Eulenflügeldickicht gesandt, um ein paar Relikte ausfindig zu machen. Ich bin nur bis hierhergekommen, bevor ich von einem wilden Ansturm von Flügelschlagen und Krallen überwältigt wurde.\n\nWie sie brüllten und hackten, {class}!\n\nHier lag ich dann, ein gebrochener Orc mit nichts weiter als meiner Rache im Sinn. Bitte, {class}, wenn Ihr auch nur ein wenig Ehrgefühl im Leib habt, werdet Ihr in das Eulenflügeldickicht ziehen und mir helfen, das zurückzuholen, was mir gehört.", sourceObjective = "Tötet 12 Eulenbestien im Eulenflügeldickicht.", completion = "Meine Ehre ist wiederhergestellt.\n\nTeilweise.\n\nMeine Geschichte setzt sich fort, {class}, denn ich habe noch weitere Teile meiner Ehre an anderen Stellen in diesem Wald verloren.\n\nEs war für mich keine sehr leichte Reise.", sourceObjectiveStatus = "unverified-source-field" }
quests[28830] = { id = 28830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Apfel fällt nicht weit vom Stamm", description = "Meine rätselhaften Wohltäter haben mir mehr als eine Aufgabe gegeben. Die zweite Aufgabe hat mich weiter nach Süden in die Frosthauchschlucht gebracht. Ich war überrascht, zu erfahren, dass die Schluchtbrücke entzwei ist und dadurch das Reisen über Land von einer Seite auf die andere unmöglich ist.\n\nDarüber hinaus wurden die jüngeren Frosthagelkipper von ihren stärkeren, ausgewachsenen Eltern getrennt. Ich dachte, dass ich sie im Kampf besiegen könnte.\n\nDa habe ich falsch gelegen. Zu meiner Schande war ich dazu gezwungen, die Flucht zu ergreifen.\n\nErteilt diesen Frosthagelkippern eine Lektion, {name}. Schlagt sie im Kampf.", sourceObjective = "Tötet 8 Frosthagelkipper.", completion = "Seid froh, dass die Schlucht die ausgewachsenen Riesen von dieser Seite abschneidet. Sie sind viel zäher als diese Frosthagelkipper, gegen die Ihr kämpft.\n\nIch fühle mich verjüngt durch Euren Mut, {class}. Vielleicht ist doch noch nicht alle Hoffnung verloren...", sourceObjectiveStatus = "unverified-source-field" }
quests[28831] = { id = 28831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hol Dich der Teufel, Frostilicus!", description = "Die Frosthagelriesen wären kein Problem gewesen, hätte es nicht diesen verdammten Frostilicus gegeben. Als die Erde bebte und die Brücke entzwei ging, traten er und seine Wasserelemente aus der Erde hervor und übernahmen den Boden der Frosthauchschlucht. So vertrieben sie die Riesen.\n\nHol Dich der Teufel, Frostilicus!\n\nIhr würdet mir eine große Ehre erweisen, wenn Ihr ihn zurück in die Erde treibt, {class}. Ihr findet ihn im Süden auf dem Boden der Schlucht.", sourceObjective = "Vernichtet Frostilicus.", completion = "Wenn ich meine Verletzungen überlebe, werde ich Euren Namen niemals vergessen, {class}.\n\nImmer wenn der Wind durch die Bäume rauscht, werde ich Euren Namen hören.\n\nHabt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[28832] = { id = 28832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtufer", description = "Also gut, steigt einfach in das Wasserflugzeug hinter mir und ich flieg' Euch ins Hochland.\n\nWir müssen uns bei 'nem Typen melden, den sie \"Leutnant Fawkes\" nennen. Ich hab' dem König versprochen, dass wir rucki-zucki dort sind, also hab' ich mir die Freiheit genommen, ein wenig überflüssiges Gewicht abzuwerfen. Zum Beispiel Sicherheitsgurte. Fallschirme. Karten. Stabilisatoren. Ein Landungsgestell.\n\nIch konnte mit diesen Dingern ohnehin nie richtig \"landen\".", sourceObjective = "Sprecht mit Leutnant Fawkes in Hochstade im Schattenhochland.", completion = "Das Letzte, was ich vom Himmel fallen zu sehen erwartet hätte, seid Ihr beide. Hochstade wird angegriffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28833] = { id = 28833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet den Erdsprecher!", description = "Gut! Ihr habt Verbündete mitgebracht.\n\nIhr müsst Euch beeilen, wenn wir Erunak retten wollen.\n\nKämpft Euch einen Weg durch Neptulons Hallen frei. Findet den Schamanen und befreit ihn von diesen Würmern... Wenn er noch lebt.\n\nHabt keine Sorge, dass sie Euch in den Rücken fallen. Nichts und niemand kommt an mir vorbei!", sourceObjective = "Rettet Erunak Steinsprecher.", completion = "Was sagt Ihr? Ihr... rettet mich?\n\n<Erunak lächelt Euch an.>\n\nEs wird etwas dauern, bis ich mich daran gewöhne.", sourceObjectiveStatus = "unverified-source-field" }
quests[28834] = { id = 28834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet den Erdsprecher!", description = "Gut! Ihr habt Verbündete mitgebracht.\n\nIhr müsst Euch beeilen, wenn wir Erunak retten wollen.\n\nGeht jetzt. Kämpft Euch einen Weg durch Neptulons Hallen frei. Findet den Schamanen und befreit ihn von diesen Würmern... Wenn er noch lebt.\n\nSorgt Euch nicht, dass sie Euch in den Rücken fallen könnten. Ich bemühe mich, dass nichts und niemand an mir vorbeikommt!", sourceObjective = "Rettet Erunak Steinsprecher.", completion = "Was sagt Ihr? Ihr... rettet mich?\n\n<Erunak lächelt Euch an.>\n\nEs wird etwas dauern, bis ich mich daran gewöhne.", sourceObjectiveStatus = "unverified-source-field" }
quests[28836] = { id = 28836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sünden der Meerhexe", description = "Diese widerliche Schlange hat einen tausendfachen Tod verdient!\n\nEs wird nicht leicht sein. Sie und ihre Diener haben sich an diesem Ort fest verschanzt, aber sie ist von ihrem Kampf gegen Neptulon sicherlich erschöpft.\n\nJetzt ist die richtige Zeit, um zuzuschlagen! Eine Möglichkeit wie diese wird sich uns nicht wieder bieten.\n\nDurchbohrt sie, {name}!", sourceObjective = "Besiegt Lady Naz'jar im Thron der Gezeiten.", completion = "Gut gemacht, {name}!\n\nIhr solltet wissen, dass ohne Eure Hilfe die Sache hier ganz anders aussehen würde.\n\nIch wäre nicht nur längst tot, sondern die Naga und ihre Verbündeten würden ungehindert über die Meere herrschen.\n\nDer König selbst soll von Euren Heldentaten in diesen Gefilden erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28837] = { id = 28837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandelbare Bestien", description = "Wir, die blauen Drachen wurden gezwungen, unsere Heimat Mazthoril zu verlassen. Ein Betrüger namens Umbranse hat den Augenblick unserer größten Ohnmacht ausgenutzt und hält nun die Höhle besetzt.\n\nMazthoril ist ein Ort extrem wirksamer Magie und er weiß sie nicht zu beherrschen. Sogar die Tiere und Pflanzen der Umgebung leiden darunter.\n\nDie Biester in der Nähe wurden gewandelt. Bitte, {race}, ich muss Euch um einen Gefallen ersuchen. Sammelt ihre Gehirne, sodass ich herausfinden kann, ob ich die wilde Magie von Umbranse rückgängig machen kann.", sourceObjective = "Beschafft 5 manaverwirrte Gehirne von wandelbaren Bestien.", progress = "Mazthoril gehört dem Blauen Drachenschwarm. Es ist nicht richtig, so wie es jetzt ist.", completion = "Lasst mich sehen, was ich damit anstellen kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[28838] = { id = 28838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Standhaftigkeit der Eulenbestien", description = "So ein Ärger. Was immer Umbranse getan hat, es verhindert, dass ich seine Magie rückgängig machen kann.\n\nEr ist weiser, als ich es erwartet hatte.\n\nAber ich habe dennoch einen Plan B. Ich habe Eulenbestien gesehen, die in Mazthoril ein und ausgehen, sogar nachdem Umbranse die Herrschaft übernommen hat. Ihre uralte, druidische Magie muss in der Lage sein, die von Umbranse unschädlich zu machen. Glücklicherweise kenne ich das Verhalten der Eulenbestien sehr genau.\n\nReist nach Süden zu Dun Mandarr. Dort findet Ihr eine Truhe mit einem Traumfänger darin.\n\nDas wird Euer erster Schritt sein.", sourceObjective = "Erlangt einen Eulenbestientraumfänger aus Dun Mandarr.", sourceObjectiveStatus = "unverified-source-field" }
quests[28839] = { id = 28839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prähistorische Magie", description = "Die heiligen Höhlen der Eulenbestien befinden sich im Osten. In einigen dieser Höhlen solltet Ihr Totems finden. Ich will, dass Ihr diese Totems auftreibt und von ihnen so viele Essenzen einsammelt, wie ihr könnt. Der Traumfänger sollte diese Essenzen aufsaugen können, sodass wir sie in Mazthoril verwenden können.", sourceObjective = "Gelangt in den Besitz der Essenz des Klauentotems, der Essenz des Lebenstotems und der Essenz des Mondtotems.", sourceObjectiveStatus = "unverified-source-field" }
quests[28840] = { id = 28840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterwasser", description = "Ich will nicht, dass unser erster Zug ein Reinfall wird, {name}. Ein derartiges Versagen würde nur unnötig Aufmerksamkeit auf unsere Bemühungen ziehen und Umbranse die Gelegenheit geben, seine Verteidigung auszubauen. Nein, wir müssen das von Anfang an richtig machen.\n\nÜber die Frosthauchschlucht im Süden haben wir Zugang zu mächtigen Eiselementaren. Das Wasser in der Außenhülle dieser Elementare sollte die Energie Eures Traumfängers verstärken und sicherstellen, dass unsere Bemühungen Früchte tragen.\n\nBeschafft dieses Wasser, {name}. Dann kehrt in unser kleines Lager zurück.", sourceObjective = "Beschafft 7 Winterwasser von Eisavataren in der Frosthauchschlucht.", progress = "Schön, Euch wiederzusehen.", completion = "<Haleh überträgt das Wasser auf Euren Traumfänger.>\n\nIhr habt gute Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28841] = { id = 28841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Versiegelung der Portale", description = "Mazthorils wilde Magie kann unvorstellbares Chaos anrichten, wenn sie falsch eingesetzt wird. Umbranses übermütiges Wirken in den Höhlen hat eine Reihe von Tesserakten geöffnet – mit anderen Worten Portale. Sie stellen Verbindungen zu anderen Welten her. Bevor ich nach Mazthoril zurückkehren kann, müssen diese Tesserakte geschlossen werden.\n\nDer Traumfänger wird die Portale schließen und so könnt Ihr sicher in Umbranses Unterschlupf eindringen. Vernichtet zunächst alles, was aus den Tesserakten hervorkommt, dann verwendet den Traumfänger, um sie schnell zu schließen, bevor sich noch etwas anderes in diese Welt ergießt.", sourceObjective = "Verwendet den machterfüllten Traumfänger, um 5 arkane Tesserakte in Mazthoril zu schließen.", completion = "Es wird etwas dauern, bis Mazthoril sich erholt... aber schließlich wird es wieder wie früher.\n\nDer blaue Drachenschwarm ist noch lange nicht tot.", sourceObjectiveStatus = "unverified-source-field" }
quests[28842] = { id = 28842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umbranses Erlösung", description = "Umbranse lauert im hinteren Teil von Mazthoril. Sein Ende ist nah.\n\nUnglücklicherweise bin ich nicht in der Lage, Euch bei dieser Aufgabe zur Seite zu stehen. Zwar würde ich gerne selbst Hand an diese Schlange legen, aber Mazthorils Magie würde mich in seinem derzeitigen Zustand in Stücke reißen. Nein, Ihr müsst dies für mich zum Abschluss bringen.\n\nWenn getan wurde, was getan werden muss, verwendet diesen Siegelring. Er wird Euch sicher zurück zum Ausgang bringen.", sourceObjective = "Besiegt Umbranse den Geistsprecher.", completion = "Ihr habt unseren Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28843] = { id = 28843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sünden der Meerhexe", description = "Naz'jar! Sie ist diejenige, die für dieses Chaos verantwortlich ist.\n\nSie ist hier irgendwo, {name}. Sie muss nach dem Kampf mit Neptulon erschöpft sein.\n\nJetzt ist die richtige Zeit, um zuzuschlagen! Eine Möglichkeit wie diese wird sich uns nicht wieder bieten.\n\nIch werde mich um alles Gewürm kümmern, was versucht, ihr aus dieser Richtung zu Hilfe zu eilen.\n\nFindet sie, {name}, und spießt sie auf!", sourceObjective = "Legionär Nazgrim will, dass Ihr Lady Naz'jar vernichtet.", completion = "Höllschrei selbst soll von Euren Taten erfahren, {name}.\n\nOhne Euch, wäre die Lage hier viel schlimmer.\n\nLok'tar ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[28845] = { id = 28845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vortexgipfel", description = "Eine unserer zivilen Führungspersonen wurde von den Luftelementaren gefangen genommen.\n\nIn diesem Augenblick foltern sie ihn vermutlich.\n\nGeht zum Vortexgipfel. Von dort stammen diese verdorbenen Kreaturen. Sucht dort nach Itesh.\n\nDer Eingang zum Vortexgipfel schwebt vor der südöstlichen Küste von Uldum.", sourceObjective = "Findet Itesh im Vortexgipfel.", completion = "Ihr kommt wirklich hierher, weil Ihr mich sucht?", sourceObjectiveStatus = "unverified-source-field" }
quests[28847] = { id = 28847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verfolgung von Umbranse", description = "Wir haben herausgefunden, wo sich Umbranse hier in Winterquell aufhält. Es ist, wie ich es mir gedacht habe.\n\nUmbranse befindet sich in Mazthoril, der Höhle im Südwesten, die einst dem blauen Drachenschwarm gehört hat. Meine Mutter Haleh wird Euch dort empfangen. Sie befindet sich mit ein paar anderen Überlebenden in einem kleinen Lager vor der Höhle.\n\nHaltet Ausschau nach ihrem Lagerfeuer.", sourceObjective = "Meldet Euch bei Haleh im Beryllaufstieg in Winterquell.", completion = "Ihr seid {name}, nicht wahr?\n\nGut, Ihr werdet von großem Nutzen sein. Ich benötige die Hilfe eines {class}, wie Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28848] = { id = 28848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spur des Geistsprechers", description = "Ich habe Geschichten über Umbranse gehört, obwohl ich ihm niemals persönlich begegnet bin. Man erzählt sich, dass er magische Artefakte sammelt, obwohl ich nicht sagen kann, zu welchem Zweck.\n\nGebt diese Information am besten an einen vertrauenswürdigen Verbündeten weiter. Nymn, der Hochelf befindet sich in der Ewigen Warte, der großen Goblinstadt im Nordosten. Erzählt ihm alles, was Ihr heute erfahren habt.", sourceObjective = "Meldet Euch bei Nymn in der Ewigen Warte in Winterquell.", completion = "Umbranse... Ich verstehe. Ich werde diese Information an mein Volk weiterleiten.\n\nIhr werdet kontaktiert, wenn Ihr wieder gebraucht werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[28849] = { id = 28849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichthimmel", description = "Ich habe gerade eine Nachricht aus Orgrimmar erhalten. Der Kriegshäuptling will, dass wir bald ausrücken. Wir wären nicht dazu in der Lage, wenn Ihr uns nicht geholfen hättet!\n\nDer Plan sieht vor, dass die Luftflotte sofort aufbricht und die Marine soll kurz darauf folgen. Höllschrei wird die Luftflotte begleiten und hat ausdrücklich verlangt, dass Ihr mit uns mitkommt.\n\nKeine Zeit zu verlieren! Geht zur Südlichen Endhaltestelle der Raketenbahn hier in Azshara und meldet Euch bei Friz Bodendreh an. Ich werde mit dem Zeppelin kommen, um Euch abzuholen.", sourceObjective = "Meldet Euch bei Friz Bodendreh an der Südlichen Endhaltestelle der Raketenbahn in Azshara an.", completion = "Noch ein {class}, wie? Von Eurer Sorte wollen gerade sehr viele ins Hochland. Hier, unterschreibt den Entschädigungsverzicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[28850] = { id = 28850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Gefängnisdach", description = "Ich verstehe nicht, warum der König meine Zeit damit verschwenden will, um diesen Unterschlupf zu kämpfen, aber wenn Ihr Euer Leben aufs Spiel setzen wollt, tut Euch keinen Zwang an.\n\nCrowley und seine Männer verstecken sich oben. Vermutlich schmieden sie gerade Pläne gegen den König.", sourceObjective = "Sprecht mit Darius Crowley oben im Steinwallgefängnis in Gilneas.", completion = "Graumähne hat Recht. Diese Bestien scheren sich einen Dreck um unsere Politik.\n\nWir in Gilneas müssen zusammenhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28852] = { id = 28852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klopft sie weich", description = "Endlich Verstärkung! Ich bin so froh, dass Ihr hier seid. Wir hätten niemals gedacht, dass die Kräfte des Schattenhammers sich hier derartig eingegraben haben. Und es sind so viele!\n\nEinige unserer Drachen wurden in der Haupthalle gefangen genommen. Bitte, löst ihre Fesseln und befreit sie.\n\nSobald sie frei sind, können wir diese Hallen mit Flammen reinigen. Klettert einfach auf einen roten Drachen und ruft die Namen Eurer Ziele. Ihr werdet die Zahl unserer Feinde sicherlich dezimieren wollen, bevor Ihr Euch tiefer in die Ruinen vorwagt.", sourceObjective = "Befreit in Grim Batol einen roten Drachen und vernichtet mit ihm 30 Troggs und 15 Anhänger des Schattenhammers.", completion = "Das sind großartige Neuigkeiten, {name}! Ich bin froh, dass unsere Drachen Euch unterstützen konnten. Habt Dank dafür, dass Ihr sie aus den Klauen des Schattenhammers befreit habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28853] = { id = 28853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet den Kurier", description = "Habt Dank dafür, {class}, dass Ihr den Schrecken dieses fürchterlichen und finsteren Ortes getrotzt habt.\n\nDie Innereien von Grim Batol sind das Herz von Cho'galls Kriegsmaschinerie. Wenn wir seinen Machenschaften im Hochland ein Ende setzen wollen, müssen wir so viel wie möglich aus diesen Tiefen in Erfahrung bringen.\n\nSucht dort drinnen nach Drahga Schattenbrenner. Er ist Cho'galls Bote, die Verbindung zwischen diesem Ort und der Bastion des Zwielichts. Wir müssen herausfinden, welche Geheimnisse er bei sich trägt.", sourceObjective = "Tötet Drahga Schattenbrenner und bringt sein Sendschreiben an Cho'gall in Euren Besitz.", progress = "Was habt Ihr herausgefunden, {class}?", completion = "<Tooranu sieht sich die Dokumente an, die Ihr gefunden habt.>\n\nHier steht alles drin, {name}. Einzelheiten, wie der Schattenhammerkult das Hochland verwüstet, wen sie ausgesandt haben, wo sie sind und was sie vorhaben. Unbezahlbar.\n\nIch werde dieses Wissen unverzüglich an den Rest des Irdenen Rings weiterleiten. Habt tausend Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[28854] = { id = 28854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Abschluss eines finsteren Kapitels", description = "Dieser schreckliche Ort war Alexstraszas Alptraum. Während des Zweiten Krieges, wie ihn die Sterblichen nennen, war sie in den Tiefen angekettet. Ihr gepeinigter Nachwuchs wurde gezwungen, der von Dämonen verderbten Horde zu dienen.\n\nAlexstrasza ist vielleicht frei, aber die Bestie namens Erudax verderbt dort unten noch immer ihren Nachwuchs.\n\n<Unheilsflammes Körper spannt sich an vor Wut.>\n\nVernichtet ihn, {class}. Zermalmt ihn, sodass wir diesen Schrecken ein für alle Mal ein Ende setzen!", sourceObjective = "Vernichtet Erudax, den Herzog aus der Tiefe.", completion = "Es ist also vollbracht.\n\nWenn ich diesen ganzen Berg zum Einsturz bringen könnte, würde ich es tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[28856] = { id = 28856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sand von Silithus", description = "Mal sehen... Oh, der hier ist gut! Silithus!\n\nAlso anscheinend braucht der Zirkel des Cenarius Hilfe bei irgendeiner Form von Insektenplage.\n\n<Vizzie zittert.>\n\nPfui! Nein danke, nichts für mich. Ich würde hier in der Ewigen Warte mit Freuden erfrieren, wenn die Alternative diese Käfer sind.\n\nHm... Hier steht, dass Besucher mit Windruferin Prachthorn sprechen sollen und der einfachste Weg dort hinzugelangen ist, den Pfad am nordwestlichen Abhang vom Krater von Un'Goro hinaufzusteigen.\n\nSeid Ihr interessiert?", sourceObjective = "Meldet Euch bei Windruferin Prachthorn in der Burg Cenarius in Silithus.", completion = "Willkommen auf Burg Cenarius.\n\n<Windruferin Prachthorn streift Euch ein wenig frischen Schnee von der Schulter.>\n\nIhr kommt ja wirklich von weit her.", sourceObjectiveStatus = "unverified-source-field" }
quests[28857] = { id = 28857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwüstete Lande: Das andere Ende der Welt", description = "Das hier ist interessant. Es besagt, dass man sich bei Rüstmeister Lungertz in Burg Nethergarde in den Verwüsteten Landen melden soll. Viel weiter kann man von hier gar nicht entfernt sein!\n\nHier heißt es, dass sie Schwierigkeiten mit Angriffen der Horde haben. Pff! Ich wusste gar nicht, dass die Horde sogar einen Außenposten in den Verwüsteten Landen hat. Soviel ich weiß, hat man dort unten zu viel mit den Dämonen zu tun, als sich mit solchen Streitigkeiten zu befassen.\n\nIhr müsst das Große Meer überqueren und dann von den Sümpfen des Elends aus nach Süden reisen.\n\nSeid Ihr interessiert?", sourceObjective = "Meldet Euch bei Rüstmeister Lungertz in Burg Nethergarde.", completion = "Seit Jahrzehnten hält die Garnison in Nethergarde gegen die Bedrohung der Horde tapfer stand und wir haben nicht vor, jetzt die Waffen zu strecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[28858] = { id = 28858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwüstete Lande: Das andere Ende der Welt", description = "Das hier ist interessant. Es besagt, dass Mitglieder der Horde mit Okrilla in der Feste Schreckensfels sprechen sollen.\n\nPfff! Ich wusste gar nicht, dass die Feste Schreckensfels in den Händen der Horde ist!\n\nIch vermute, Okrilla benötigt Hilfe beim Kampf gegen ein paar Oger und die Allianz. Man könnte meinen, dass sie bereits alle Hände voll mit diesen Dämonen dort unten zu tun hätte!\n\nDer beste Weg zur Feste Schreckensfels ist über das Große Meer, dann müsst Ihr von den Sümpfen des Elends aus den Weg nach Süden nehmen.\n\nSeid Ihr interessiert?", sourceObjective = "Meldet Euch bei Okrilla in der Feste Schreckensfels in den Verwüsteten Landen.", completion = "Unsere Feinde sind zahlreich, {class}. Es wird Geschick und Mut erfordern, sie alle zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28859] = { id = 28859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dünen von Silithus", description = "Burg Cenarius in Silithus ist die größte Druidensiedlung in Kalimdor. Sie ist fast so groß wie die Mondlichtung, Mann.\n\nEines Tages wird Zen'Aliri vielleicht zur Burg Cenarius hinübertapern... gegen ein paar Schattenhammerkultisten kämpfen, das Land in Ordnung bringen, wo die Silithiden es zerstören... Aber Zen'Aliris Meister befiehlt ihm zu warten.\n\nAlso wartet Zen'Aliri.\n\nDer einfachste Weg dorthin führt über den Pfad am nordwestlichen Hang des Kraters von Un'Goro hinauf.\n\nWenn Ihr keinen Meister habt... dann hält Euch doch nichts davon ab, loszuziehen.", sourceObjective = "Meldet Euch bei Windruferin Prachthorn in der Burg Cenarius in Silithus.", completion = "Willkommen auf Burg Cenarius, Reisender.", sourceObjectiveStatus = "unverified-source-field" }
quests[28860] = { id = 28860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Angehörigen des Drachenmals in Schach halten", description = "Dank Eurer Hilfe haben wir den Mitgliedern des Drachenmals einen ziemlich harten Schlag versetzt, aber ihre täglichen Angriffe in den Außenbezirken Donnermars setzen sie fort. Wir müssen weiterhin Druck auf sie ausüben!\n\nBegebt Euch zurück in die Schlacht, die in den Ruinen im Süden und Südwesten von Donnermar tobt. Tötet die Drachenmalmarodeure und sammelt die Insignien, die ihre größten Krieger tragen.", sourceObjective = "Tötet Drachenmalmarodeure und sammelt 8 Insignien des Drachenmals. Feindliche Charaktere in den Ruinen von Donnermar, die einen Namen haben, tragen ebenfalls Insignien bei sich.", progress = "Wie läuft der Kampf, {class}?", completion = "Aye, so macht man das! Wenn sich Helden wie Ihr um unsere Angelegenheiten kümmern, erfüllt es mich mit Stolz, ein Mitglied der Allianz zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[28861] = { id = 28861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kämpfen wie ein Wildhammer", description = "<Blundy dreht seine Tasse um.>\n\nMein Bier ist alle, {name}!\n\nZieht los in die Ruinen von Donnermar und seht, ob dort noch etwas ist, bevor diese schäbigen Drachenmalorcs sich daran vergreifen.\n\nNehmt selbst einen kräftigen Zug, wenn Euch danach ist. Ein Krug von Donnermars Feinstem wird Eure Kampfkünste beflügeln.", sourceObjective = "Sammelt 10 Fässer voll Donnermarbier aus den Ruinen von Donnermar. Aber vorschischt - das hat tschiemlich viele Umdrehungen!", progress = "Habta was?", completion = "Oha, waschfür ein Fang!\n\nDaschwird sischerlisch... bischmorgen reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28862] = { id = 28862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Essen zurücklassen", description = "Flüchtlinge strömen nach den Kämpfen noch immer nach Donnermar und ich habe Hunger! Ich meine sie. Die Flüchtlinge. Sie haben Hunger.\n\nBesorgt mir aus den Ruinen von Donnermar was zu Essen! Durchforstet die Ruinen im Süden, Osten und Südwesten nach zurückgebliebenen Vorräten. Besonders diese fetten Schinken. Die liebe ich! Ähm, die Flüchtlinge lieben sie, meine ich.\n\nUnd seht zu, dass Ihr ein paar von diesen kleinen Cocktailwürstchen auftreibt.", sourceObjective = "Sammelt 10 Nahrungsmittelvorräte der Wildhämmer in den Ruinen von Donnermar.", progress = "Habt Ihr was zu Essen?", completion = "Oh ja, Ihr kommt gerade rechtzeitig! Ich bin hungrig vom vielen Arbeiten. Es macht ganz schön viel Arbeit, Essen an diese hungrigen Flüchtlinge zu verteilen. Jawohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[28863] = { id = 28863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsherr Halthar ist zurück", description = "Er tut es schon wieder, {name}. Kriegsherr Halthar... Schrecken der Auen. Er und seine Drachen wurden dabei beobachtet, wie sie im Süden Unheil inmitten der Ruinen von Donnermar anrichten.\n\nTötet Halthar, {name}! Wir werden ein paar Kriegsmeuten aussenden, um Euch zu helfen, sobald Ihr in den Kampf verwickelt seid.", sourceObjective = "Tötet den Kriegsherrn Halthar.", completion = "Ein finsteres Geschäft, aber dennoch gut, dass es vollbracht ist. Habt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28864] = { id = 28864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bierlieferung", description = "Nach der Hochzeit meiner Schwester habe ich dieses Donnerbräu-Lagerbier getrunken und bin auf den Geschmack gekommen. Kurdran hat es aus Dun Morogh importiert. Es befindet sich noch mehr auf dem Weg hierher, aber unsere Karawane wird immer wieder von diesen Banditen des Drachenmals angegriffen.\n\nBegebt Euch die südöstliche Seite des Bergs Donnerschlag hinauf und schließt Euch der Karawane an. Haltet am Wegesrand Ausschau nach einem Gesellen namens Hammerhand und Helft ihm dabei, das Gebräu über den Pass zu schaffen.\n\nWenn Ihr es sicher bis nach Kirthafen bringt, übernehmen wir es von dort.", sourceObjective = "Sprecht mit Hammerhand auf der Straße südöstlich des Bergs Donnerschlag und begleitet eine Versorgungskarawane bis nach Kirthafen.", progress = "Ist die Straße frei? Oder haben die Drachenmalorcs wieder Schwierigkeiten gemacht?", completion = "Man stelle sich das mal vor. Hätte nie gedacht, dass ich mal eine Vorliebe für Importbier entwickeln würde. Habt Dank, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28865] = { id = 28865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Kriegsmatrone", description = "Unsere altehrwürdige Kriegsmatrone Okrilla hat mich in die entlegensten Teile der Welt entsendet, um nach geeigneten Helden zu suchen, die sich unserer Sache anschließen wollen. Seid Ihr daran interessiert, den Einfluss der Horde auf die Östlichen Königreiche zu erweitern? Dann nehmt dieses Portal in die Verwüsteten Lande und meldet Euch bei Okrilla in der Feste Schreckensfels.", sourceObjective = "Meldet Euch bei Okrilla in der Feste Schreckensfels in den Verwüsteten Landen.", completion = "Silithus, so ein wertloses Stück Land. Es ist ein Wunder, dass der große Kataklysmus es nicht vollständig gespalten hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[28866] = { id = 28866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Steinernen Kern", description = "Ihr sagtet, dass sich dieser Millhaus Manasturm und Hohepriesterin Azil im Inneren des Steinernen Kerns treffen sollten?\n\nKlingt nach etwas Großem. Wir heften uns besser an ihre Fersen. Wir wollen nicht, dass die Schattenhammerkultisten hinter unserem Rücken irgendetwas Großes durchziehen.\n\nSprecht mit Erdwächterin Yrsa im Steinernen Kern. Sie wurde dort stationiert, um sicherzugehen, dass die Mitglieder des Schattenhammers nicht versuchen, den Tempel der Erde zurückzuerobern.", sourceObjective = "Sprecht mit der Erdwächterin Yrsa im Steinernen Kern.", completion = "Es wird aber auch Zeit, dass sie Hilfe schicken.\n\nMillhaus Manasturm? Das klingt so, als ob wir hinter derselben Person her sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28867] = { id = 28867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nethergarde braucht Euch!", description = "Nethergarde braucht Euch, {class}! Ich wurde von Rüstmeister Lungertz hergesandt, um Okrillas schändliche Lakaien abzufangen und einsatzfähige Helden der Allianz anzuwerben! Helft uns, die Horde abzuwehren!\n\nWenn Ihr Euch bereiterklärt, nehmt dieses Portal vor mir in die Verwüsteten Lande und sprecht mit dem Rüstmeister.", sourceObjective = "Sprecht mit Rüstmeister Lungertz in der Burg Nethergarde in den Verwüsteten Landen.", completion = "Silithus. Kein besonders einladender Ort, oder? Von dort kommen viele Eurer Sorte...", sourceObjectiveStatus = "unverified-source-field" }
quests[28868] = { id = 28868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Luft hier unten", description = "Wir müssen die Errichtung dieses Frostmähnendorfes verhindern. Wenn wir es zulassen, dass sie sich hier zu sehr festsetzen, wird es umso schwieriger werden, sie davon abzuhalten, sich hier dauerhaft niederzulassen.\n\nEs wird Zeit, diesen Schlägertypen den Blickwinkel eines Gnoms zu verpassen! Nehmt diesen Blickwinkelausgleicher und setzt ihn gegen die Bauarbeiter der Frostmähnen ein, um sie mit uns auf Augenhöhe zu bringen. Sie werden nicht mehr in der Lage sein, ihre Werkzeuge anzuheben und die Bauarbeiten werden erliegen.", sourceObjective = "Setzt den Blickwinkelausgleicher gegen 5 Bauarbeiter der Frostmähnen in der Zuflucht der Frostmähnen ein.", completion = "Gut gemacht, {name}. Das wird sie lehren, sich mit uns in unserer Heimat anzulegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28869] = { id = 28869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kieselchen", description = "Falls Ihr es noch nicht bemerkt habt: Es gibt einen sehr kleinen Elementar, der Gefallen an Euch gefunden hat. Falls Ihr einige Augenblicke auf dem Boden verharrt, werdet Ihr ihn sicherlich entdecken.\n\nIhr scheint ziemlich gut darin, Euch hier unten Freunde zu machen. Das ist eine nützliche Eigenschaft.", sourceObjective = "Sprecht mit Kieselchen in den Berstenden Säulen. Falls Ihr lange genug auf dem Boden bleibt, sollte er aus seinem Versteck kommen, um Euch zu suchen.", completion = "<Kieselchen scheint ziemlich froh, Euch kennenzulernen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28870] = { id = 28870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Verlorenen Stadt", description = "Wir haben vielleicht Neferset eingenommen, aber die Tol'vir von Neferset haben nun ein neues Machtzentrum.\n\nDank Siamat, dem mächtigen Herrscher des Südwinds, sind die Tol'vir von Neferset nun deutlich gefährlicher geworden.\n\nWir haben soeben erfahren, dass ein Teil von Naduns Aufklärungstruppen, die in den Hinterhalt geraten sind, es geschafft haben, den Eingang der Verlorenen Stadt zu sichern.\n\nGeht und macht Hauptmann Hadan ausfindig. Beschafft Euch sämtliche Informationen, die Ihr benötigt, um Siamat und den Nefersetabschaum zu erledigen.", sourceObjective = "Sprecht mit Hauptmann Hadan in der Verlorenen Stadt der Tol'vir.", completion = "Seid gegrüßt, {name}. Nadun hielt große Stücke auf Euch.\n\nSeid Ihr hier, um uns zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[28871] = { id = 28871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet die Wildhämmer", description = "Die Mitglieder des Wildhammers werden durch ihre neuen Verbündeten von der Allianz langsam dreist. Sie wagen es, von der anderen Seite des Flusses Druck auszuüben. Treibt sie zurück!\n\nFindet und vernichtet die Kriegsmeuten der Wildhämmer, die in dem Flussbett und in den Ruinen von Donnermar am nördlichen Ufer kämpfen. Die besten unter ihnen tragen Insignien bei sich. Sammelt sie für mich ein, um Eure Loyalität für die Sache des Drachenmals unter Beweis zu stellen.", sourceObjective = "Tötet so lange Kriegsgezeichnete des Wildhammers, bis Ihr 8 Insignien der Wildhämmer gesammelt habt. Feindliche Charaktere in den Ruinen von Donnermar, die einen Namen haben, tragen ebenfalls Insignien bei sich.", progress = "Zeigt mir die Insignien, die Ihr gesammelt habt, {class}.", completion = "Da sieh mal einer an! Ein einziges Mitglied der Horde schlägt die Wildhammerzwerge dutzendfach. Welche Hoffnung bleibt ihnen jetzt noch?", sourceObjectiveStatus = "unverified-source-field" }
quests[28872] = { id = 28872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenkrieg", description = "Einige der Wildhämmer klammern sich noch immer an die Hoffnung, die Ruinen von Donnermar im Norden auf der anderen Flussseite zurückzuerobern. Räuchert sie aus! Zerschmettert offene Fässer voll Donnermarbier. Das üble Gebräu ist so stark, dass es explodiert, wenn man es entzündet.\n\nFragt mich nicht warum.\n\nUnd fragt mich nicht, wie sie dieses Zeug runterbringen.", sourceObjective = "Zerschmettert 10 Fässer voll Donnermarbier in den Ruinen von Donnermar.", completion = "Ja, ja. Räuchert sie aus, als würdet Ihr Murmeltiere aus Ihrem Bau scheuchen wollen...\n\nGut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28873] = { id = 28873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein weiterer Magen zu füllen", description = "<Griffs Magen knurrt.>\n\nNoch immer hungrig. Es ist wie... jeden Tag. Ich bin hungrig.\n\nIch habe gehört, dass noch mehr Vorräte in den Ruinen von Donnermar auf der anderen Flussseite im Norden lagern, dort wo so viel gekämpft wird. Bringt mir etwas davon her.", sourceObjective = "Sammelt 10 Nahrungsmittelvorräte der Wildhämmer in den Ruinen von Donnermar.", progress = "<Griff leckt seine Lippen.>", completion = "<Griff krallt sich gierig den riesigen Berg an Lebensmitteln – genug, um dutzende von Männern satt zu bekommen.>\n\nGroßartig! Das hilft mir über die nächsten... Stunden hinweg!", sourceObjectiveStatus = "unverified-source-field" }
quests[28874] = { id = 28874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greifhaken", description = "Die Wildhämmer dressieren ihre Kriegsgreife schneller, als wir unsere Drachen unterwerfen und beherrschen können. Wir dürfen nicht zulassen, dass sie uns weiter zahlenmäßig überlegen sind!\n\nJagt die Greifenreiter, die über den Fluss nördlich der Blutschlucht fliegen. Nehmt diesen Haken und schleudert ihn nach ihnen, wenn sie vorüberfliegen. Durch ihren Schwung werden sie von ihrem Reittier gerissen und landen direkt vor Euren Füßen. Tötet dann die aus dem Sattel geworfenen Greifenreiter!", sourceObjective = "Verwendet den gestachelten Fleischerhaken, um 4 Greifenreiter von Donnermar aus dem Sattel zu holen und zu töten.", completion = "Bei Euch sah das so leicht aus, {name}.\n\nHolt die Wildhämmer von ihren Reittieren und ihr Leben ist keine Glühkappe mehr wert!", sourceObjectiveStatus = "unverified-source-field" }
quests[28875] = { id = 28875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt den Hochschamanen", description = "Unsere Späher dort draußen berichten, dass der Hochschamane MacKilligan von Donnermar ausgerückt ist. Er kämpft in den Ruinen von Donnermar nordwestlich von hier auf der anderen Flussseite.\n\nEr ist gefährlich, {name}, verantwortlich für den Tod vieler Mitglieder des Drachenmals. Er WIRD getötet werden, das ist nicht die Frage.\n\nDie Frage lautet: Wer wird derjenige sein, der sich rühmen können wird, ihn getötet zu haben? Ihr?", sourceObjective = "Vernichtet den Hochschamanen MacKilligan.", completion = "Der Hochschamane ist gefallen! Donnermar wird zweifellos versuchen, andere zu entsenden, aber an diesem Tag sind die Mitglieder des Drachenmals siegreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[28876] = { id = 28876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Schutzwall von Mor'shan", description = "Kadrak am Schutzwall von Mor'shan im Norden bittet um Unterstützung.\n\nDer Schutzwall liegt an der Grenze zwischen dem Nördlichen Brachland und dem Eschental. Er bildet die Frontlinie des Kampfes gegen die Allianz.\n\nWir treiben die Nachtelfen aus dem Wald. Wir beanspruchen die Ressourcen für die Horde!\n\nUm dorthin zu gelangen, nehmt vom Wegekreuz aus die Goldstraße nach Norden.\n\nDas Schicksal ruft!", sourceObjective = "Meldet Euch bei Kadrak am Schutzwall von Mor'shan an der Grenze zwischen dem Nördlichen Brachland und dem Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[28877] = { id = 28877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie nennen ihn Schnelldolch. Er tötet Harpyien.", description = "Im Westen lebt ein Orc. Am zerbröckelnden Rand der vernichtenden Kluft, die der Kataklysmus hinterlassen hat.\n\nSie nennen ihn Schnelldolch, {name}. Sie nennen ihn deshalb so, weil... sein... im Grunde ist das einfach nur sein Name, glaub' ich.\n\n<Düsentopf zuckt die Schultern.>\n\nWie dem auch sei, er ist eine Harpyienkillermaschine. Er tötet Harpyien. Er liebt es. Er lebt dafür. Geht und sucht ihn auf! Seht Euch an, wie er das macht. Lebt den Traum. Vielleicht macht Ihr das irgendwann noch hauptberuflich.", sourceObjective = "Findet Darsok Schnelldolch im Nördlichen Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[28878] = { id = 28878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk" }
quests[28879] = { id = 28879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Waisenhaus", description = "Wir viel Spaß mit dir hatten, {name}. Wir uns wünschen so sehr, du könntest <unser Papa/unsere Mama> sein, aber du uns jetzt zur Waisenmatrone Aria in Dalaran zurückbringen musst.\n\nDu uns vielleicht irgendwann wieder besuchen kommen? Es toll war, Winterflossenjungen zu treffen und Drachenkönigin zu sehen. Es uns wird keiner glauben, dass wir einen Großen getroffen haben!\n\nWir dich werden vermissen, {name}. Wir versprechen, dir mal einen Brief zu schreiben, oki?", sourceObjective = "Bringt Euren Schutzbefohlenen zurück zum Waisenhaus in Dalaran, indem Ihr der Waisenmatrone Aria in Dalaran die Pfeife des Orakelwaisenkindes überreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28880] = { id = 28880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Waisenhaus", description = "Weißt du was? So schlecht bist du gar nicht, {name}. Du nimmst Kekek mit zu Orten, an denen was los ist. Kekek trifft viele neue Freunde und macht Dinge, die kein anderer Welpe macht.\n\nDu und Hemet Nesingwary und Schneewehenwelpen alle neue beste Freunde. Vielleicht du irgendwann das Grünehügelbuch bringen? Kekek verspricht, dir auch ab und zu zu schreiben, um zu sagen, wie die Dinge stehen. Vielleicht sogar nett sein zu Großzungenkindern.\n\nKekek muss jetzt zur Waisenmatrone Aria zurückkehren, zurück in Lilaleutestadt.", sourceObjective = "Bringt Euren Schutzbefohlenen zurück zum Waisenhaus in Dalaran, indem Ihr der Waisenmatrone Aria in Dalaran die Pfeife des Wolvarwaisenkindes überreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28881] = { id = 28881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabungsleiter Gunstan", description = "Sagt mal... Ihr wart noch nicht in den Südmondruinen, oder? Oh, Ihr MÜSST einfach hin. Da sind alle möglichen faszinierenden Titanenartefakte. Geht nach Westen, und haltet nach den Zelten der Forscherliga Ausschau.", sourceObjective = "Meldet Euch bei Ausgrabungsleiter Gunstan in den Südmondruinen in Tanaris.", completion = "Was, seid Ihr hier, um zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[28882] = { id = 28882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg in Tol Barad", description = "Wir haben uns den Brückenkopf auf diesem hässlichen Felsbrocken hart erkämpft und wir werden uns die Horde auf gar keinen Fall in die Quere kommen lassen. Die Kontrolle über Tol Barad zu behalten ist unsere oberste Priorität und wir brauchen dafür Eure Hilfe, {name}. Erringt den Sieg in Tol Barad und kehrt mit Nachricht über unseren Sieg zu mir zurück.", sourceObjective = "Erringt einen Sieg in Tol Barad und kehrt zu Major Marsden im Baradinbasislager auf der Halbinsel von Tol Barad zurück.", completion = "Den Geruch kenne ich doch. Ah... der Duft des Sieges. Eure Bemühungen in Tol Barad sind ein großer Triumph für die Allianz und Euer Beitrag soll nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28884] = { id = 28884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg in Tol Barad", description = "Unsere strategischen Pläne hier in den Östlichen Königreichen stehen und fallen mit der Kontrolle über Tol Barad, {race}. Wir müssen alle Register ziehen, um die Allianz von dieser Insel fernzuhalten und dafür brauchen wir Eure Hilfe. Kämpft mit allen verfügbaren Mitteln, um die Kontrolle über Tol Barad zu erringen und überbringt mir Kunde von unserem Sieg.", sourceObjective = "Erringt einen Sieg in Tol Barad und kehrt zu Oberst Karzag in Höllschreis Griff auf der Halbinsel von Tol Barad zurück.", completion = "Ihr bringt Kunde über unseren Sieg, ganz wie erwartet! Jeder Sieg in Tol Barad ist ein Sieg für die Horde. Ihr könnt Euch sicher sein, dass Eure Mühen hier belohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28885] = { id = 28885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wilde Fahrt des Herrn Goldmine", description = "Nun dann, {name}, wir müssen es zum Erdportal am Ende dieser Höhle schaffen.\n\nIch habe uns einen fahrbaren Untersatz \"beschafft\". Warum sollten wir laufen, wenn wir stilvoll fahren können? Ich hoffe, Ihr habt nichts gegen Minenwagen.\n\nSagt mir Bescheid, wenn Ihr soweit seid.", sourceObjective = "Fahrt in dem Minenwagen zusammen mit Initiand Goldmine bis zum Ende der Gleise.", completion = "Oh nein! Meine Waffen und Totems!\n\nSie sind zerstört!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[28905] = { id = 28905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täglicher zufälliger, heroischer Dungeon (Erster) (Cataclysm)" }
