quests[28908] = { id = 28908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täglicher, zufälliger, normaler Dungeon (Nter)" }
quests[28909] = { id = 28909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sauranok wird den Weg weisen", description = "Wie ich sehe, habt Ihr noch nicht mit meinem Berater, Sauranok dem Mystiker, gesprochen. Seit unserer gemeinsamen Kampagne in Nordend ist er nicht von meiner Seite gewichen.\n\nUm das Schattenhochland anzugreifen, brauchen wir eine Karte des Küstenstreifens. Ich habe Sauranok die Aufgabe gebeben, diese Information bereitzustellen. Seht nach, ob er Eure Hilfe benötigt! Er steht direkt neben mir.", sourceObjective = "Sprecht mit Sauranok dem Mystiker in der Feste Grommash in Orgrimmar.", completion = "<Sauranok nickt Euch zu.>\n\n{class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28910] = { id = 28910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Allianz im Nördlichen Schlingendorntal!", sourceObjectiveStatus = "unverified-source-field" }
